let backendCustomTypes=null;
function customTypes(){if(backendCustomTypes)return backendCustomTypes;try{return JSON.parse(store.get("captypes","{}"))}catch(e){return{}}}
function allTypes(){return Object.assign({},BUILTIN_TYPES,customTypes());}
function classify(name){const ext=(name.split(".").pop()||"").toLowerCase();const T=allTypes();
  for(const[k,v]of Object.entries(T))if((v.ext||[]).includes(ext))return k;return "file";}
function typeIcon(type){const T=allTypes();const t=T[type];
  if(t&&t.svg)return '<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8">'+t.svg+'</svg>';
  if(t&&t.emoji)return '<span class="u76">'+esc(t.emoji)+'</span>';
  return '<span class="u76">\u{1F4CE}</span>';}
function typeLabel(type){const t=allTypes()[type];return t?t.label:"File";}

/* markdown */
function md(src){src=String(src).replace(/(^|\n)(!\[[^\n]*\]\([^\n]+\))(?=\n|$)/g,"$1\n$2\n");const blocks=src.split(/\n{2,}/);let out="";
  for(let b of blocks){b=b.replace(/\r/g,"");
    const recording=b.trim().match(/^:::terminal-recording\s+(.+?)\s*:::$/);if(recording){out+='<div class="termrecord" contenteditable="false" data-recording="'+encodeURIComponent(recording[1])+'"><div class="termrecordbar"><button type="button" data-castplay>Play</button><button type="button" data-castrestart>Restart</button><button type="button" data-castai title="Register and approve this recording for mission-scoped AI">Use as AI evidence</button><span>'+esc(recording[1].split(/[\\/]/).pop())+'</span><button type="button" data-castup title="Move before previous paragraph">↑</button><button type="button" data-castdown title="Move after next paragraph">↓</button><button type="button" data-castdelete title="Remove recording from note">Delete</button></div><div data-castterm></div></div>';continue;}
    const imageText=b.trim(),captionedImage=imageText.match(/^!\[([^\]]*)\]\((.+)\s+"([^"]*)"\)$/),plainImage=imageText.match(/^!\[([^\]]*)\]\((.+)\)$/),image=captionedImage||plainImage;if(image){out+=imageBlockHTML(image[1],image[2].trim(),captionedImage?image[3]:"");continue;}
    if(/^```/.test(b)){const ml=b.match(/^```([a-z0-9+#.-]*)/i);const lang=ml?ml[1]:"";const code=b.replace(/^```[a-z0-9+#.-]*\n?/i,"").replace(/```\s*$/,"");out+="<pre"+(lang?' data-lang="'+esc(lang)+'"':"")+"><code>"+esc(code)+"</code></pre>";continue;}
    if(/^\s*\|/.test(b)&&/\n\s*\|/.test(b)){const rows=b.trim().split("\n").filter(r=>r.trim());const ce=r=>r.trim().replace(/^\||\|$/g,"").split("|").map(c=>c.trim());
      out+="<table><thead><tr>"+ce(rows[0]).map(c=>"<th>"+inl(c)+"</th>").join("")+"</tr></thead><tbody>";rows.slice(2).forEach(r=>out+="<tr>"+ce(r).map(c=>"<td>"+inl(c)+"</td>").join("")+"</tr>");out+="</tbody></table>";continue;}
    if(/^#{1,6}\s/.test(b)){const lines=b.split("\n"),m=lines.shift().match(/^(#{1,6})\s+(.*)/);out+="<h"+m[1].length+">"+inl(m[2])+"</h"+m[1].length+">";if(lines.length)out+="<p>"+inl(lines.join("\n"))+"</p>";continue;}
    if(/^>\s/.test(b)){out+="<blockquote>"+inl(b.replace(/^>\s?/gm,""))+"</blockquote>";continue;}
    if(/^\s*[-*]\s/.test(b)){out+="<ul>"+b.split("\n").map(l=>l.replace(/^\s*[-*]\s+/,"")).filter(Boolean).map(l=>"<li>"+inl(l)+"</li>").join("")+"</ul>";continue;}
    if(/^\s*\d+\.\s/.test(b)){out+="<ol>"+b.split("\n").map(l=>l.replace(/^\s*\d+\.\s+/,"")).filter(Boolean).map(l=>"<li>"+inl(l)+"</li>").join("")+"</ol>";continue;}
    out+="<p>"+inl(b)+"</p>";}
  return out;
  function safeURI(raw,image=false){try{const u=new URL(raw,location.href),scheme=u.protocol.toLowerCase();if(scheme==="https:"||scheme==="http:")return raw;if(image&&scheme==="data:"&&/^data:image\/(png|jpeg|gif|webp);base64,/i.test(raw))return raw;}catch(e){}return "";}
  function inl(t){return esc(t).replace(/`([^`]+)`/g,(_,c)=>"<code>"+c+"</code>")
    .replace(/!\[([^\]]*)\]\(([^)]+)\)/g,(_,alt,uri)=>{const safe=safeURI(uri,true);return safe?'<img alt="'+alt+'" src="'+esc(safe)+'">':alt;})
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g,(_,label,uri)=>{const safe=safeURI(uri);return safe?'<a href="'+esc(safe)+'" target="_blank" rel="noopener">'+label+'</a>':label;})
    .replace(/\*\*([^*]+)\*\*/g,"<strong>$1</strong>")
    .replace(/(^|[^*])\*([^*]+)\*/g,"$1<em>$2</em>").replace(/\[(F-\d+)\]/g,'<span class="chip low u77">$1</span>').replace(/\n/g,"<br>");}
}
function safeImageURI(raw){raw=String(raw||"").trim();if(/^assets\/[A-Za-z0-9._-]+$/.test(raw)||/^https?:\/\//i.test(raw)||/^data:image\/(png|jpeg|gif|webp);base64,/i.test(raw))return raw;return "";}
function imageBlockHTML(alt,src,caption="",displaySrc=src){src=String(src||"").trim();displaySrc=safeImageURI(displaySrc||src);if(!displaySrc)return '<p class="empty">Blocked unsafe image source: '+esc(src)+'</p>';return '<figure class="imageblock" contenteditable="false" data-alt="'+encodeURIComponent(alt)+'" data-src="'+encodeURIComponent(src)+'" data-caption="'+encodeURIComponent(caption)+'"><div class="termrecordbar"><button type="button" data-imgcopy>Copy</button><button type="button" data-imgcaption>'+(caption?'Edit caption':'Add caption')+'</button><button type="button" data-imgup title="Move before previous paragraph">↑</button><button type="button" data-imgdown title="Move after next paragraph">↓</button><button type="button" data-imgdelete>Delete</button></div><img alt="'+esc(alt)+'" src="'+esc(displaySrc)+'"><figcaption>'+esc(caption)+'</figcaption></figure>';}
function promoteLooseImages(root){let changed=false,last=null;for(const image of $$("img",root)){if(image.closest(".imageblock")||image.closest(".reportbrand"))continue;const src=image.getAttribute("src")||"",alt=image.getAttribute("alt")||"pasted";if(!src)continue;const wrap=document.createElement("div");wrap.innerHTML=imageBlockHTML(alt,src,"",src);last=wrap.firstElementChild;image.replaceWith(last);changed=true;}if(changed){mountImageBlocks(root);ensureTextAfterMedia(root,last,true);}return changed;}
function renderedToMarkdown(root){function walk(n){if(n.nodeType===3)return n.nodeValue;if(n.nodeType!==1)return "";const tag=n.tagName.toLowerCase(),inner=[...n.childNodes].map(walk).join("");if(n.classList?.contains("termrecord"))return ":::terminal-recording "+decodeURIComponent(n.dataset.recording||"")+" :::\n\n";if(n.classList?.contains("imageblock")){const caption=decodeURIComponent(n.dataset.caption||"").replace(/"/g,"'"),src=decodeURIComponent(n.dataset.src||"").trim();return "!["+decodeURIComponent(n.dataset.alt||"")+"]("+src+(caption?' "'+caption+'"':"")+")\n\n";}
  if(/^h[1-6]$/.test(tag))return "#".repeat(+tag[1])+" "+inner+"\n\n";if(tag==="p"||tag==="div")return inner+"\n\n";if(tag==="br")return "\n";if(tag==="strong"||tag==="b")return "**"+inner+"**";if(tag==="em"||tag==="i")return "*"+inner+"*";if(tag==="code"&&n.parentElement?.tagName!=="PRE")return "`"+inner+"`";if(tag==="pre")return "```\n"+n.textContent+"\n```\n\n";if(tag==="blockquote")return n.textContent.split("\n").map(x=>"> "+x).join("\n")+"\n\n";if(tag==="li")return inner+"\n";if(tag==="ul")return [...n.children].map(x=>"- "+walk(x).trim()).join("\n")+"\n\n";if(tag==="ol")return [...n.children].map((x,i)=>(i+1)+". "+walk(x).trim()).join("\n")+"\n\n";if(tag==="a")return "["+inner+"]("+(n.getAttribute("href")||"")+")";if(tag==="img")return "!["+(n.getAttribute("alt")||"")+"]("+(n.getAttribute("src")||"")+")";return inner;}
 return [...root.childNodes].map(walk).join("").replace(/\n{3,}/g,"\n\n").trim();}

/* ---------- layout state ---------- */
let targetScope="container",engineFilter="all",missionQuery="";
const IMAGE_REPAIRS=new Set();
function repairPastedImageText(m,text,apply){if(!online)return false;const patterns=[/x-special\/nautilus-clipboard\s*\n(?:copy|cut)\s*\n(file:\/\/[^\n]+\.(?:png|jpe?g|gif|webp))/i,/\[[^\]]*\]\((file:\/\/[^)]+\.(?:png|jpe?g|gif|webp))\)/i,/(^|\n)((?:file:\/\/|[A-Za-z]:[\\/]|\/)[^\n]+\.(?:png|jpe?g|gif|webp))(?=\n|$)/i],match=patterns.map(p=>text.match(p)).find(Boolean);if(!match)return false;const uri=[match[1],match[2]].find(x=>/^(?:file:\/\/|[A-Za-z]:[\\/]|\/)/i.test(x||"")),whole=match[0],key=m.id+"\0"+uri;if(!uri)return false;if(IMAGE_REPAIRS.has(key))return true;IMAGE_REPAIRS.add(key);B.ImportNoteImage(m.id,uri).then(saved=>{const replacement=(whole.startsWith("\n")?"\n":"")+"\n![pasted]("+saved.path+")\n\n";apply(text.replace(whole,replacement));toast("Pasted image recovered and copied into mission notes/assets");}).catch(err=>toast("Pasted image could not be imported: "+((err&&err.message)||err))).finally(()=>IMAGE_REPAIRS.delete(key));return true;}
function defaultLayout(){return {rows:[{h:1,cols:[{panels:["notebook"],active:"notebook",w:1},{panels:["console","assistant","config","findings","captures","secrets"],active:"console",w:1.15}]}]};}
const layouts={};
function layoutOf(id){if(!layouts[id]){const raw=store.get("layout:"+id,null);let value=raw?JSON.parse(raw):defaultLayout();if(value.cols&&!value.rows)value={rows:[{h:1,cols:value.cols}]};if(!value.rows?.length)value=defaultLayout();layouts[id]=value;}return layouts[id];}
function allLayoutCols(L){return L.rows.flatMap(r=>r.cols);}
function saveLayout(id){store.set("layout:"+id,JSON.stringify(layouts[id]));}
let curMission=store.get("rfsw-mission",MISSIONS[0].id);
if(!mission(curMission))curMission=MISSIONS[0].id;

/* ---------- rail ---------- */
function worst(p){return p.crit?"crit":p.high?"high":p.med?"med":"ok";}
function renderRail(){
  const list=$("#mList");list.innerHTML="";
  const containers=MISSIONS.filter(m=>m.engine!=="nix"),nixenvs=MISSIONS.filter(m=>m.engine==="nix");$("#containerCount").textContent=containers.length;$("#nixCount").textContent=nixenvs.length;
  const scoped=targetScope==="nix"?nixenvs:containers,q=missionQuery.toLowerCase(),vis=scoped.filter(m=>(targetScope==="nix"||engineFilter==="all"||m.engine===engineFilter)&&(!q||[m.id,m.title,m.engine,m.image,m.env].some(v=>String(v||"").toLowerCase().includes(q))));
  $("#mCount").textContent=vis.length+"/"+scoped.length;
  if(!vis.length){list.innerHTML='<div class="empty">no '+(targetScope==="nix"?"Nix environments":"containers")+' match this view</div>';}
  vis.forEach(m=>{const w=worst(m.environmentAudit||{crit:0,high:0,med:0,low:0}),fw=worst(m.findingSummary||{crit:0,high:0,med:0,low:0}),fc=Object.values(m.findingSummary||{}).reduce((a,b)=>a+(+b||0),0),stt=missionState(m),native=m.engine==="nix";
    const b=document.createElement("div");b.className="mcard"+(m.id===curMission?" active":"");b.dataset.missionId=m.id;b.tabIndex=0;b.setAttribute("role","button");if(m.id===curMission)b.setAttribute("aria-current","true");
    b.innerHTML=`<div class="l1"><span class="st ${native||stt==="up"?"":stt==="starting"?"starting":"off"}" title="${native?"ready (native)":esc(stt)}"></span><span class="nm">${esc(m.id)}</span><span class="sp"></span>
        ${fc?`<span class="chip ${fw}" title="${fc} mission finding(s)"><span class="d"></span>${fc} findings</span>`:""}<span class="chip ${w}" title="tool environment audit warning"><span class="d"></span>env</span></div>
      <div class="l2"><span class="eng ${esc(m.engine)}">${esc(m.engine)}</span><span class="chip ${native||stt==="up"?"ok":"low"}"><span class="d"></span>${native?"ready":esc(stt)}</span><button class="life" data-life ${native||stt==="starting"||stt==="stopping"?"disabled":""}>${native?"Native":stt==="up"?"Stop":"Start"}</button></div>`;
    b.onclick=()=>{curMission=m.id;store.set("rfsw-mission",m.id);maxCol=null;renderRail();requestAnimationFrame(()=>$(".mcard.active",list)?.scrollIntoView({block:"nearest"}));renderMissionBar();renderDock();if(online)selectMissionData(m.id);};
    b.onkeydown=e=>{if(e.key==="Enter"||e.key===" "){e.preventDefault();b.click();}};b.oncontextmenu=e=>{e.preventDefault();openMissionContext(e.clientX,e.clientY,m);};const life=b.querySelector("[data-life]");if(life)life.onclick=e=>{e.stopPropagation();if(native)return;stt==="up"?stopMission(m):startMission(m);};
    list.appendChild(b);});
}
$$("#efilter button").forEach(b=>b.onclick=()=>{engineFilter=b.dataset.e;$$("#efilter button").forEach(x=>x.classList.toggle("active",x===b));renderRail();});
$$('[data-scope]').forEach(b=>b.onclick=()=>{targetScope=b.dataset.scope;$$('[data-scope]').forEach(x=>x.classList.toggle("active",x===b));$("#efilter").style.display=targetScope==="container"?"flex":"none";$("#createMission").textContent="New mission";$("#importTarget").title=targetScope==="nix"?"Import a portable Nix environment":"Import a container archive";$("#refreshTargets").lastChild.textContent=targetScope==="nix"?"Refresh Nix environments":"Refresh containers";renderRail();});
$("#missionSearch").oninput=e=>{missionQuery=e.target.value.trim();renderRail();};

/* ---------- mission lifecycle (start/stop; sequential boot) ---------- */
function missionState(m){return m.stopping?"stopping":m.starting?"starting":(m.up?"up":"stopped");}
function startMission(m){return new Promise(res=>{if(m.up||m.starting){res();return;}m.starting=true;renderRail();renderMissionBar();if(mission(curMission)===m)renderDock();
  setTimeout(()=>{m.starting=false;m.up=true;renderRail();renderMissionBar();if(mission(curMission)===m)renderDock();res();},700);});}
function stopMission(m){if(!m.up&&!m.starting)return;m.up=false;m.starting=false;renderRail();renderMissionBar();if(mission(curMission)===m)renderDock();toast("Stopped "+m.id+" ("+ENGNAME[m.engine]+")");}
async function bootAll(){const list=MISSIONS.filter(m=>m.up);list.forEach(m=>{m.up=false;});renderRail();renderMissionBar();if(mission(curMission))renderDock();
  for(const m of list){await startMission(m);}toast("Missions started");}

/* ---------- mission bar ---------- */
function renderMissionBar(){const m=mission(curMission);
  if(!m){$("#mTitle").textContent="No RF Swift targets";$("#mPath").textContent="Create a container or Nix environment with the CLI, then refresh";const rb=$("#runBtn");if(rb){rb.textContent="No target";rb.disabled=true;}return;}
  $("#mTitle").textContent=m.title||m.id;
  $("#mPath").textContent=m.id+"  ~/.rfswift/missions/"+m.id+"  ("+ENGNAME[m.engine]+")";
  const st=missionState(m);const rb=$("#runBtn");if(rb){
    if(st==="starting"){rb.textContent="Starting...";rb.disabled=true;rb.onclick=null;}
    else if(st==="stopping"){rb.textContent="Stopping...";rb.disabled=true;rb.onclick=null;}
    else if(m.engine==="nix"){rb.disabled=true;rb.textContent="Native Nix environment";rb.onclick=null;}
    else if(st==="up"){rb.disabled=false;rb.textContent="Stop mission";rb.onclick=()=>stopMission(m);}
    else{rb.disabled=false;rb.textContent="Start mission";rb.onclick=()=>startMission(m);}}
}
$("#resetBtn").onclick=()=>{layouts[curMission]=defaultLayout();maxCol=null;saveLayout(curMission);renderDock();toast("Layout reset");};
$("#addPanelBtn").onclick=(e)=>{e.stopPropagation();const menu=$("#addMenu");
  const L=layoutOf(curMission);const present=new Set(allLayoutCols(L).flatMap(c=>c.panels));
  menu.innerHTML=Object.entries(PANELS).map(([id,p])=>`<button data-add="${id}" ${present.has(id)?"disabled":""}>${picon(id)} ${p.t}${present.has(id)?" (open)":""}</button>`).join("");
  menu.classList.toggle("open");
  $$("#addMenu button[data-add]").forEach(bn=>bn.onclick=()=>{const id=bn.dataset.add;
    const row=L.rows[L.rows.length-1],last=row.cols[row.cols.length-1];last.panels.push(id);last.active=id;maxCol=null;saveLayout(curMission);menu.classList.remove("open");renderDock();});
};
document.addEventListener("click",e=>{if(!$("#addMenu").contains(e.target)&&e.target!==$("#addPanelBtn"))$("#addMenu").classList.remove("open");});

/* ---------- dock ---------- */
let drag=null;              // {panel} being dragged
let colEls=[];
let maxCol=null;            // "row:column" of the maximized panel, or null
const EXPAND_SVG='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 9V4h5M20 15v5h-5M15 4h5v5M9 20H4v-5"/></svg>';
const RESTORE_SVG='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 4v5H4M15 20v-5h5M20 9h-5V4M4 15h5v5"/></svg>';
function toggleMax(ri,ci){const key=ri+":"+ci;maxCol=(maxCol===key)?null:key;renderDock();}
function removePanel(pid){const L=layoutOf(curMission);let emptied=-1;
  for(let ri=0;ri<L.rows.length;ri++)for(let i=0;i<L.rows[ri].cols.length;i++){const c=L.rows[ri].cols[i],k=c.panels.indexOf(pid);
    if(k>=0){c.panels.splice(k,1);if(c.active===pid)c.active=c.panels[0]||null;
      if(!c.panels.length){L.rows[ri].cols.splice(i,1);emptied={ri,ci:i,rowRemoved:false};if(!L.rows[ri].cols.length){L.rows.splice(ri,1);emptied.rowRemoved=true;}}if(!L.rows.length)L.rows.push({h:1,cols:[]});return emptied;}}
  if(!L.rows.length)L.rows.push({h:1,cols:[{panels:["console"],active:"console",w:1}]});
  return emptied;
}
function buildCol(col,ri,ci,m,lone){
  const isTerm=col.active==="console"||col.active==="assistant";
  const colEl=document.createElement("div");colEl.className="dockcol"+(isTerm?" term-col":"");colEl.style.flexGrow=lone?1:(col.w||1);
  const strip=document.createElement("div");strip.className="colstrip";
  col.panels.forEach(pid=>{const tab=document.createElement("div");tab.className="ptab"+(pid===col.active?" active":"");tab.draggable=true;
    tab.innerHTML=picon(pid)+"<span>"+PANELS[pid].t+"</span><span class='x' title='close'>&times;</span>";
    tab.onclick=(e)=>{if(e.target.classList.contains("x")){maxCol=null;removePanel(pid);saveLayout(curMission);renderDock();return;}col.active=pid;saveLayout(curMission);renderDock();};
    tab.addEventListener("dragstart",e=>{drag={panel:pid};tab.classList.add("dragging");e.dataTransfer.effectAllowed="move";e.dataTransfer.setData("text/plain",pid);});
    tab.addEventListener("dragend",()=>{drag=null;tab.classList.remove("dragging");$$(".dz").forEach(d=>d.classList.remove("over"));$$(".colstrip").forEach(s=>s.classList.remove("dropok"));});
    strip.appendChild(tab);});
  const grow=document.createElement("div");grow.className="colgrow";strip.appendChild(grow);
  const mx=document.createElement("button");mx.className="colbtn";mx.title=lone?"Restore columns":"Expand column (hide the others)";
  mx.innerHTML=lone?RESTORE_SVG:EXPAND_SVG;mx.onclick=(e)=>{e.stopPropagation();toggleMax(ri,ci);};strip.appendChild(mx);
  strip.addEventListener("dragover",e=>{if(drag){e.preventDefault();strip.classList.add("dropok");}});
  strip.addEventListener("dragleave",()=>strip.classList.remove("dropok"));
  strip.addEventListener("drop",e=>{e.preventDefault();strip.classList.remove("dropok");if(!drag)return;const pid=drag.panel;
    if(col.panels.includes(pid)){col.active=pid;}else{removePanel(pid);col.panels.push(pid);col.active=pid;}
    saveLayout(curMission);renderDock();});
  colEl.appendChild(strip);
  const body=document.createElement("div");body.className="colbody";body.innerHTML=col.active?panelBody(col.active,m):"<div class='empty'>empty</div>";
  colEl.appendChild(body);
  return colEl;
}
function renderDock(){
  const m=mission(curMission);const dock=$("#dock");dock.innerHTML="";colEls=[];
  if(!m){dock.innerHTML='<div class="empty">No live RF Swift containers or Nix environments were found.</div>';return;}
  const L=layoutOf(curMission);
  if(maxCol!=null){
    const [ri,ci]=maxCol.split(":").map(Number),col=L.rows[ri]?.cols[ci];if(!col)maxCol=null;else{const colEl=buildCol(col,ri,ci,m,true);dock.appendChild(colEl);colEls.push(colEl);if(col.active)wirePanel(col.active,m);return;}
  }
  dock.appendChild(makeRowDropzone(0));L.rows.forEach((row,ri)=>{
    const rowEl=document.createElement("div");rowEl.className="dockrow";rowEl.style.flexGrow=row.h||1;
    row.cols.forEach((col,ci)=>{rowEl.appendChild(makeDropzone(ri,ci));const colEl=buildCol(col,ri,ci,m,false);rowEl.appendChild(colEl);colEls.push({ri,ci,el:colEl});if(ci<row.cols.length-1){const rz=document.createElement("div");rz.className="colresize";rz.addEventListener("pointerdown",e=>startResize(e,ri,ci));rowEl.appendChild(rz);}});
    rowEl.appendChild(makeDropzone(ri,row.cols.length));dock.appendChild(rowEl);
    if(ri<L.rows.length-1)dock.appendChild(makeRowSeparator(ri));
  });
  dock.appendChild(makeRowDropzone(L.rows.length));
  allLayoutCols(L).forEach(col=>{if(col.active)wirePanel(col.active,m);});
}
function makeDropzone(ri,i){const dz=document.createElement("div");dz.className="dz";dz.dataset.i=i;
  dz.addEventListener("dragover",e=>{if(drag){e.preventDefault();dz.classList.add("over");}});
  dz.addEventListener("dragleave",()=>dz.classList.remove("over"));
  dz.addEventListener("drop",e=>{e.preventDefault();dz.classList.remove("over");if(!drag)return;const pid=drag.panel,L=layoutOf(curMission);let idx=i;const emptied=removePanel(pid);if(emptied&&emptied.ri===ri&&emptied.ci<idx)idx--;const row=L.rows[Math.min(ri,L.rows.length-1)]||{h:1,cols:[]};if(!L.rows.includes(row))L.rows.push(row);idx=Math.max(0,Math.min(idx,row.cols.length));row.cols.splice(idx,0,{panels:[pid],active:pid,w:1});saveLayout(curMission);renderDock();});
  return dz;
}
function makeRowDropzone(i){const dz=document.createElement("div");dz.className="rowdz";dz.addEventListener("dragover",e=>{if(drag){e.preventDefault();dz.classList.add("over");}});dz.addEventListener("dragleave",()=>dz.classList.remove("over"));dz.addEventListener("drop",e=>{e.preventDefault();dz.classList.remove("over");if(!drag)return;const pid=drag.panel,L=layoutOf(curMission);let idx=i;const emptied=removePanel(pid);if(emptied?.rowRemoved&&emptied.ri<idx)idx--;L.rows=L.rows.filter(r=>r.cols.length);idx=Math.max(0,Math.min(idx,L.rows.length));L.rows.splice(idx,0,{h:1,cols:[{panels:[pid],active:pid,w:1}]});saveLayout(curMission);renderDock();});return dz;}
function makeRowSeparator(ri){const rz=document.createElement("div");rz.className="rowresize";rz.title="Drag vertically to resize rows, or drop a panel here to create a row";rz.addEventListener("pointerdown",e=>startRowResize(e,ri,rz));rz.addEventListener("dragover",e=>{if(drag){e.preventDefault();rz.classList.add("over");}});rz.addEventListener("dragleave",()=>rz.classList.remove("over"));rz.addEventListener("drop",e=>{e.preventDefault();rz.classList.remove("over");if(!drag)return;const pid=drag.panel,L=layoutOf(curMission);let idx=ri+1,emptied=removePanel(pid);if(emptied?.rowRemoved&&emptied.ri<idx)idx--;L.rows=L.rows.filter(r=>r.cols.length);L.rows.splice(Math.max(0,Math.min(idx,L.rows.length)),0,{h:1,cols:[{panels:[pid],active:pid,w:1}]});saveLayout(curMission);renderDock();});return rz;}
function startResize(e,ri,ci){const L=layoutOf(curMission),row=L.rows[ri],a=row?.cols[ci],b=row?.cols[ci+1];if(!a||!b)return;const ae=colEls.find(x=>x.ri===ri&&x.ci===ci)?.el,be=colEls.find(x=>x.ri===ri&&x.ci===ci+1)?.el;
  const x0=e.clientX,wa=a.w||1,wb=b.w||1,sum=wa+wb,pxSum=(ae.offsetWidth+be.offsetWidth)||1;
  e.preventDefault();
  const move=ev=>{let na=wa+(ev.clientX-x0)/pxSum*sum;let nb=sum-na;const min=0.3;
    if(na<min){na=min;nb=sum-min;}if(nb<min){nb=min;na=sum-min;}
    a.w=na;b.w=nb;ae.style.flexGrow=na;be.style.flexGrow=nb;};
  const up=()=>{document.removeEventListener("pointermove",move);document.removeEventListener("pointerup",up);saveLayout(curMission);};
  document.addEventListener("pointermove",move);document.addEventListener("pointerup",up);
}
function startRowResize(e,ri,handle){const L=layoutOf(curMission),a=L.rows[ri],b=L.rows[ri+1];if(!a||!b)return;const rows=$$(".dockrow",$("#dock")),first=rows[ri],second=rows[ri+1],y0=e.clientY,startA=first.getBoundingClientRect().height,startB=second.getBoundingClientRect().height,total=startA+startB,minPx=Math.min(72,total*.3);e.preventDefault();handle?.setPointerCapture?.(e.pointerId);handle?.classList.add("resizing");const move=ev=>{const nextA=Math.max(minPx,Math.min(total-minPx,startA+ev.clientY-y0)),nextB=total-nextA;first.style.flex=`0 0 ${nextA}px`;second.style.flex=`0 0 ${nextB}px`;a.h=nextA/total;b.h=nextB/total;};const up=()=>{document.removeEventListener("pointermove",move);document.removeEventListener("pointerup",up);handle?.classList.remove("resizing");first.style.flex=`${a.h} 1 0px`;second.style.flex=`${b.h} 1 0px`;saveLayout(curMission);};document.addEventListener("pointermove",move);document.addEventListener("pointerup",up);}

/* ---------- panel bodies ---------- */
function panelBody(id,m){
  if(id==="config")return cfgHTML(m);
  if(id==="notebook")return `<div class="nbbar"><span class="t">${esc(m.id)}/notes/note.md</span><div class="spacer u10"></div>
     <div class="seg" data-nb><button data-m="render" class="active">Rendered</button><button data-m="source">Source</button></div>
     <button class="btn ghost sm" data-nbimg title="Attach image">Img</button>
     <button class="btn ghost sm" data-nbrecordings title="Browse, play and add mission recordings">Recordings</button>
     <button class="btn ghost sm" data-nbai title="AI draft (optional)">AI</button>
     <button class="btn ghost sm" data-nbexport>Export</button></div>
     <div class="reclibrary notrecordings" data-reclibrary></div>${formatToolbar("nbview")}<div class="rendered" id="nbview" data-nbview contenteditable="true" spellcheck="true" title="Edit directly; right-click selected text for formatting">${md(noteVal(m))}</div><textarea class="nbsrc u13" data-nbsrc>${esc(noteVal(m))}</textarea>`;
  if(id==="console")return `<div data-termroot><div class="termtabs" data-termtabs></div><div class="termtools"><select data-termshell aria-label="Shell"><option value="/bin/zsh">zsh</option><option value="/bin/bash">bash</option><option value="/bin/sh">sh</option></select><label title="Start recording automatically when connecting"><input type="checkbox" data-termrecord> Record on connect</label><button data-termdir title="Choose recording destination">Destination...</button><span data-termpath title="Default: this mission's recordings folder">mission recordings/</span><button data-termrectoggle title="Start or stop a recording segment without disconnecting" class="u13">Start REC</button><button data-termnote title="Embed the latest recording in the mission note" class="u13">Add recording to note</button><button data-recordings title="Browse and rename saved recordings">Recordings</button><button data-termstart>Connect</button><button data-termstop class="u13">Disconnect</button><span class="spacer"></span><span data-termstatus>${m.engine==="nix"?"Nix PTY - ":""}disconnected</span></div><div class="reclibrary" data-reclibrary></div><div class="termhost" data-xterm></div></div>`;
  if(id==="findings")return findHTML(m);
  if(id==="captures")return capHTML(m);
  if(id==="secrets")return secretsHTML(m);
  if(id==="assistant"){const c=aiCfg();return `<div class="chat"><div class="agentcompose"><textarea data-agentprompt aria-label="Agent prompt"></textarea><div class="agentfoot"><span data-agentstatus hidden></span><button class="btn sm send" data-agentsend>Send</button></div></div><div class="chatlog u78"><div class="agentempty" data-agentempty><div class="inner"><div class="mark">✦</div><strong>${c.enabled?esc(aiTag())+" is ready":"No coding agent connected"}</strong><p>${c.enabled?"Connect below to open a mission-scoped terminal. Notes, findings, tool recommendations and authorized commands will be available through MCP.":"Choose a local coding-agent CLI and permissions in Configure, then connect it to this mission."}</p></div></div><div data-agentxterm class="u79"></div></div><div class="chatbar"><button class="btn ghost sm" data-agentcfg>Configure</button><span class="spacer"></span><button class="btn sm" data-agentlaunch>Connect</button><button class="btn ghost sm u13" data-agentstop>Disconnect</button></div></div>`;}
  return "<div class='empty'>panel</div>";
}
function formatToolbar(target){return `<div class="fmtbar" data-fmtbar="${target}"><select data-heading aria-label="Text and heading style" title="Choose paragraph or heading level"><option value="">Text style</option><option value="p">Paragraph</option><option value="h1">Title - H1</option><option value="h2">Section - H2</option><option value="h3">Subsection - H3</option><option value="h4">Heading - H4</option><option value="h5">Heading - H5</option><option value="h6">Heading - H6</option></select><button type="button" data-fmt="bold" title="Bold"><b>B</b></button><button type="button" data-fmt="italic" title="Italic"><i>I</i></button><button type="button" data-fmt="insertUnorderedList" title="Bulleted list">• List</button><button type="button" data-fmt="insertOrderedList" title="Numbered list">1. List</button><button type="button" data-fmt="formatBlock" data-val="blockquote" title="Quote">❝</button><button type="button" data-fmt="formatBlock" data-val="pre" title="Code block">&lt;/&gt;</button><button type="button" data-fmt="exitBlock" title="Exit code or quote block and continue as regular text">¶ Text</button><button type="button" data-fmt="createLink" title="Link">Link</button><button type="button" data-fmt="removeFormat" title="Clear inline formatting">Clear</button><button type="button" data-fmt="ai" title="Ask AI about selection or whole document">✦ AI</button></div>`;}
let editorContext=null,editorContextTarget=null,editorContextLink=null;
function removeEditorLink(editor,link){editor.focus();if(link&&link.tagName==="A"){const parent=link.parentNode;while(link.firstChild)parent.insertBefore(link.firstChild,link);parent.removeChild(link);}else{document.execCommand("unlink",false,null);}editor.dispatchEvent(new Event("input",{bubbles:true}));}
function appendPlainParagraph(editor,block){const p=document.createElement("p");p.innerHTML="<br>";(block||editor.lastElementChild)?.after(p);if(!p.parentElement)editor.append(p);const sel=getSelection(),range=document.createRange();range.selectNodeContents(p);range.collapse(true);sel.removeAllRanges();sel.addRange(range);editor.dispatchEvent(new Event("input",{bubbles:true}));return p;}
function editorRange(editor){const sel=getSelection();return sel&&sel.rangeCount&&editor.contains(sel.anchorNode)?sel.getRangeAt(0):null;}
function selectedEditorBlocks(editor){const range=editorRange(editor);if(!range)return[];return [...editor.children].filter(el=>{try{return range.intersectsNode(el);}catch(e){return false;}});}
function replaceEditorBlock(block,tag){if(!block||block.tagName.toLowerCase()===tag)return block;const next=document.createElement(tag);if(block.tagName==="PRE")next.textContent=block.textContent;else while(block.firstChild)next.append(block.firstChild);block.replaceWith(next);return next;}
function placeCaretInBlock(block){const sel=getSelection(),range=document.createRange();range.selectNodeContents(block);range.collapse(false);sel.removeAllRanges();sel.addRange(range);}
function setEditorBlock(editor,tag){const range=editorRange(editor),node=range&&(range.commonAncestorContainer.nodeType===3?range.commonAncestorContainer.parentElement:range.commonAncestorContainer),current=node?.closest("h1,h2,h3,h4,h5,h6,p,pre,blockquote");if(tag==="pre"&&current?.tagName==="PRE"){placeCaretInBlock(replaceEditorBlock(current,"p"));return;}const blocks=selectedEditorBlocks(editor).filter(x=>/^(H[1-6]|P|PRE|BLOCKQUOTE|DIV)$/.test(x.tagName));if(blocks.length){const changed=blocks.map(x=>replaceEditorBlock(x,tag));placeCaretInBlock(changed[changed.length-1]);return;}document.execCommand("formatBlock",false,"<"+tag+">");}
function clearEditorFormat(editor){document.execCommand("unlink",false,null);document.execCommand("removeFormat",false,null);const blocks=selectedEditorBlocks(editor).filter(x=>/^(H[1-6]|PRE|BLOCKQUOTE)$/.test(x.tagName));if(blocks.length)placeCaretInBlock(replaceEditorBlock(blocks[blocks.length-1],"p"));for(const block of blocks.slice(0,-1))replaceEditorBlock(block,"p");}
function applyFormat(editor,cmd,val){if(!editor)return;if(cmd==="ai"){askEditorAI(editor);return;}editor.focus();if(cmd==="createLink"){openLinkDialog(editor);return;}if(cmd==="unlink"){removeEditorLink(editor,editorContextLink);editorContextLink=null;return;}if(cmd==="exitBlock"){const sel=getSelection(),node=sel&&sel.anchorNode,block=node&&(node.nodeType===3?node.parentElement:node)?.closest("pre,blockquote");appendPlainParagraph(editor,block);return;}if(cmd==="formatBlock")setEditorBlock(editor,val||"p");else if(cmd==="removeFormat")clearEditorFormat(editor);else document.execCommand(cmd,false,val||null);editor.dispatchEvent(new Event("input",{bubbles:true}));}
let aiEditResolve=null;
function closeAIEdit(value=null){$("#aiEditModal").classList.remove("open");if(aiEditResolve){const done=aiEditResolve;aiEditResolve=null;done(value);}}
function openLinkDialog(editor){const sel=getSelection(),range=sel&&sel.rangeCount?sel.getRangeAt(0).cloneRange():null,selected=sel?sel.toString():"";aiEditResolve=null;$("#aiEditTitle").textContent="Insert link";$("#aiEditBody").innerHTML=`<p class="aiedit-help">Add a web link without leaving the editor.</p><label class="fld">URL<input id="linkURL" value="https://" inputmode="url" autocomplete="url"></label><label class="fld u18">Text<input id="linkText" value="${esc(selected)}" placeholder="Link label"></label><div class="aiedit-actions"><button class="btn ghost sm" data-linkcancel>Cancel</button><button class="btn sm" data-linkinsert>Insert link</button></div>`;const close=()=>$("#aiEditModal").classList.remove("open");$('[data-linkcancel]',$("#aiEditBody")).onclick=close;$('[data-linkinsert]',$("#aiEditBody")).onclick=()=>{const url=$("#linkURL").value.trim(),text=$("#linkText").value||url;if(!/^https?:\/\//i.test(url)){toast("Use an http:// or https:// URL");return;}close();editor.focus();if(range){sel.removeAllRanges();sel.addRange(range);}if(selected){document.execCommand("createLink",false,url);}else document.execCommand("insertHTML",false,`<a href="${esc(url)}">${esc(text)}</a>`);editor.dispatchEvent(new Event("input",{bubbles:true}));};$("#aiEditModal").classList.add("open");setTimeout(()=>{$("#linkURL").focus();$("#linkURL").select();},0);}
function requestAIInstruction(scope){return new Promise(resolve=>{aiEditResolve=resolve;$("#aiEditTitle").textContent="Edit with "+aiTag();$("#aiEditBody").innerHTML=`<div class="aiedit-scope">✦ ${esc(scope)}</div><p class="aiedit-help">Describe how the AI should transform the ${esc(scope)}. Only this content is sent with your instruction.</p><div class="aiedit-presets"><button class="btn ghost sm" data-aipreset="Improve clarity and preserve the technical meaning">Improve clarity</button><button class="btn ghost sm" data-aipreset="Summarize concisely">Summarize</button><button class="btn ghost sm" data-aipreset="Turn this into clear remediation steps">Remediation steps</button><button class="btn ghost sm" data-aipreset="Correct spelling and grammar without changing the meaning">Proofread</button></div><textarea class="aiedit-input" id="aiEditInput" placeholder="For example: rewrite this as concise assessment notes..." spellcheck="true"></textarea><div class="aiedit-actions"><span class="status">Enter to submit - Shift+Enter for a new line</span><button class="btn ghost sm" data-aicancel>Cancel</button><button class="btn sm" data-aisend>Generate</button></div>`;const body=$("#aiEditBody"),input=$("#aiEditInput");$$('[data-aipreset]',body).forEach(b=>b.onclick=()=>{input.value=b.dataset.aipreset;input.focus();});$('[data-aicancel]',body).onclick=()=>closeAIEdit();$('[data-aisend]',body).onclick=()=>{const v=input.value.trim();if(v)closeAIEdit(v);};input.onkeydown=e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();const v=input.value.trim();if(v)closeAIEdit(v);}};$("#aiEditModal").classList.add("open");setTimeout(()=>input.focus(),0);});}
function reviewAIResult(scope,answer){return new Promise(resolve=>{aiEditResolve=resolve;$("#aiEditTitle").textContent="Review AI result";$("#aiEditBody").innerHTML=`<div class="aiedit-scope">✦ ${esc(scope)}</div><p class="aiedit-help">Review the generated Markdown before replacing the original content.</p><div class="aiedit-preview">${esc(answer)}</div><div class="aiedit-actions"><span class="status">The document is unchanged until you replace it.</span><button class="btn ghost sm" data-aicancel>Keep original</button><button class="btn sm" data-aireplace>Replace ${esc(scope)}</button></div>`;const body=$("#aiEditBody");$('[data-aicancel]',body).onclick=()=>closeAIEdit(false);$('[data-aireplace]',body).onclick=()=>closeAIEdit(true);$("#aiEditModal").classList.add("open");});}
async function askEditorAI(editor){if(!aiCfg().enabled){toast("Enable the optional MCP agent bridge first");return;}const sel=getSelection(),selected=sel&&editor.contains(sel.anchorNode)?sel.toString():"",scope=selected?"selected text":"whole document",source=selected||renderedToMarkdown(editor),instruction=await requestAIInstruction(scope);if(!instruction)return;const prompt=instruction+"\n\nUse the RF Swift MCP tools for mission "+curMission+". Update the relevant Markdown note with the result. Preserve PwnDoc-compatible finding fields when editing findings.\n\nCONTEXT:\n"+source;try{await sendAgentPrompt(curMission,prompt);toast("Instruction submitted to "+aiTag());}catch(e){toast("Connect the mission agent first: "+((e&&e.message)||e));}}
function wireFormatToolbar(root=document){$$('[data-fmtbar]',root).forEach(bar=>{const editor=$("#"+bar.dataset.fmtbar),heading=$("[data-heading]",bar);if(heading){let savedRange=null;heading.onmousedown=()=>{const sel=getSelection();savedRange=sel&&sel.rangeCount&&editor.contains(sel.anchorNode)?sel.getRangeAt(0).cloneRange():null;};heading.onchange=()=>{if(heading.value){editor.focus();if(savedRange){const sel=getSelection();sel.removeAllRanges();sel.addRange(savedRange);}applyFormat(editor,"formatBlock",heading.value);}heading.value="";savedRange=null;};}$$('[data-fmt]',bar).forEach(btn=>btn.onmousedown=e=>{e.preventDefault();applyFormat(editor,btn.dataset.fmt,btn.dataset.val);});});$$('[contenteditable="true"]',root).forEach(editor=>{editor.oncontextmenu=e=>{const ctxLink=e.target.closest&&e.target.closest("a");if(!getSelection()?.toString()&&!ctxLink)return;e.preventDefault();editorContextTarget=editor;editorContextLink=ctxLink||null;if(!editorContext){editorContext=document.createElement("div");editorContext.className="editorctx";editorContext.innerHTML='<button data-c="formatBlock" data-v="h1">Title - H1</button><button data-c="formatBlock" data-v="h2">Section - H2</button><button data-c="formatBlock" data-v="h3">Subsection - H3</button><button data-c="formatBlock" data-v="p">Paragraph</button><button data-c="bold"><b>Bold</b></button><button data-c="italic"><i>Italic</i></button><button data-c="exitBlock">¶ Regular text</button><button data-c="createLink">Link</button><button data-c="unlink">Remove link</button><button data-c="removeFormat">Clear inline style</button><button data-c="ai">✦ Ask AI</button>';document.body.appendChild(editorContext);editorContext.onmousedown=ev=>{const b=ev.target.closest("button");if(!b)return;ev.preventDefault();applyFormat(editorContextTarget,b.dataset.c,b.dataset.v);editorContext.classList.remove("open");};}editorContext.style.left=Math.min(e.clientX,innerWidth-440)+"px";editorContext.style.top=Math.min(e.clientY,innerHeight-90)+"px";editorContext.classList.add("open");};if(!editor.dataset.codeEscape){editor.dataset.codeEscape="1";editor.addEventListener("keydown",e=>{if(e.key!=="Enter"||e.shiftKey)return;const sel=getSelection(),node=sel&&sel.anchorNode,pre=node&&(node.nodeType===3?node.parentElement:node)?.closest("pre");if(!pre||!sel.rangeCount)return;const before=document.createRange();before.selectNodeContents(pre);before.setEnd(sel.anchorNode,sel.anchorOffset);const text=before.toString();if(pre.textContent.trim()!==""&&!/\n\s*$/.test(text))return;e.preventDefault();appendPlainParagraph(editor,pre);});}});}
document.addEventListener("mousedown",e=>{if(editorContext&&!editorContext.contains(e.target))editorContext.classList.remove("open");if(terminalContext&&!terminalContext.contains(e.target))terminalContext.classList.remove("open");});
document.addEventListener("click",e=>{const link=e.target.closest?.(".xterm a");if(!link)return;e.preventDefault();e.stopImmediatePropagation();const uri=link.href||link.textContent.trim();if(uri)B.OpenExternalURL(uri).catch(err=>toast("Open link failed: "+((err&&err.message)||err)));},true);
$("#aiEditClose").onclick=()=>closeAIEdit();
$("#aiEditModal").addEventListener("click",e=>{if(e.target.id==="aiEditModal")closeAIEdit();});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&$("#aiEditModal").classList.contains("open"))closeAIEdit();});
function chatMsg(x){return '<div class="msg '+(x.role==="u"?"u":"a")+'"><div class="who">'+(x.role==="u"?"you":esc(x.tag||"AI"))+'</div>'+esc(x.text)+'</div>';}
function repaintAssistant(m){const log=$("[data-chatlog]");if(!log)return;log.innerHTML=(m.ai||[]).map(chatMsg).join("");log.scrollTop=log.scrollHeight;const inp=$("[data-chat]");if(inp)inp.focus();}
function noteVal(m){return store.get("note:"+m.id,m.note);}
function cfgHTML(m){const p=m.environmentAudit||{crit:0,high:0,med:0,low:0},issues=m.auditIssues||[];const w=worst(p);const wn={crit:"critical",high:"high",med:"medium",ok:"clear"}[w];const st=missionState(m);
 const native=m.engine==="nix";const stchip=native?["ok","ready (native)"]:st==="up"?["ok","running"]:st==="starting"?["med","starting"]:["low","stopped"];
 return `<div class="pad">
   <div class="card"><div class="cardhead"><h3>Configuration</h3><span class="u20"><span class="chip low"><span class="d"></span>${ENGNAME[m.engine]}</span><span class="chip ${stchip[0]}"><span class="d"></span>${stchip[1]}</span></span></div>
     <table class="kv">
      <tr><td>Engine</td><td class="mono">${m.engine}</td></tr>
      <tr><td>Environment</td><td class="mono">${m.env}</td></tr>
      <tr><td>${m.engine==="nix"?"Store path":"Image"}</td><td class="mono">${esc(m.image)}</td></tr>
      <tr><td>User</td><td class="mono">${m.user} ${m.user==="root"?'<span class="chip med"><span class="d"></span>root</span>':""}</td></tr>
      <tr><td>Capabilities</td><td class="mono">${m.caps.length?m.caps.join(", "):"default"}</td></tr>
      <tr><td>Device cgroups</td><td class="mono">${(m.cgroups||[]).length?m.cgroups.map(esc).join("<br>"):"none"}</td></tr>
      <tr><td>Mounts</td><td class="mono">${m.mounts.map(esc).join("<br>")}</td></tr>${summaryRows(m)}${m.desktopURL?`<tr><td>Remote desktop</td><td><span class="mono">${esc(m.desktopURL)}</span> <button class="btn ghost sm" data-desktopcopy>Copy link</button> <button class="btn ghost sm" data-desktopopen>Open</button></td></tr>`:""}</table></div>
   <div class="card"><div class="cardhead"><h3>Network</h3><span class="chip ${/host/.test(m.net)?"high":"low"}"><span class="d"></span>${esc(m.net)}</span></div>
     ${networkRows(m)}<table class="ports"><thead><tr><th>Port</th><th>Published</th><th>Service</th></tr></thead><tbody>
      ${m.ports.map(r=>`<tr><td>${r[0]}</td><td>${/0\.0\.0\.0/.test(r[1])?'<span class="u80">'+r[1]+'</span>':r[1]}</td><td>${r[2]}</td></tr>`).join("")}</tbody></table></div>
   <div class="card"><div class="cardhead"><h3>Tool environment security</h3><span class="chip ${w}"><span class="d"></span>${wn}</span></div>
     <div class="posture">
      <div class="stat"><div class="n u33">${p.crit}</div><div class="l">critical</div></div>
      <div class="stat"><div class="n u80">${p.high}</div><div class="l">high</div></div>
      <div class="stat"><div class="n u81">${p.med}</div><div class="l">medium</div></div>
      <div class="stat"><div class="n u82">${p.low}</div><div class="l">low</div></div></div>
     <div class="u83">${esc(m.cnote)} <button class="btn ghost sm u84" data-audit>(Re)run audit</button> <button class="btn ghost sm" data-auditai>Audit with AI</button></div>
     <div class="u85">Warnings concern only the Nix tool closure or container image you are using. They do not change mission risk, findings, CVSS, or PwnDoc reports. Runtime-closure matches are counted; build-time matches remain informational.</div>
     <div class="auditprogress" data-auditprogress><div class="audittrack"><div class="auditfill" data-auditfill></div></div><div class="auditstage" data-auditstage>Preparing audit...</div></div>
     <details class="auditresults" ${issues.length?"open":""}><summary>Detailed environment problems <span class="chip ${w}"><span class="d"></span>${issues.length} records</span><span data-auditvisible class="u86"></span></summary><div class="audittools"><input type="search" data-auditsearch placeholder="Search CVE, package, version or scanner..."><button class="btn ghost sm active" data-auditfilter="all">All</button><button class="btn ghost sm" data-auditfilter="critical">Critical</button><button class="btn ghost sm" data-auditfilter="high">High</button><button class="btn ghost sm" data-auditfilter="medium">Medium</button><button class="btn ghost sm" data-auditfilter="low">Low</button></div><div class="auditissues">${issues.length?issues.map(i=>{const sev=String(i.severity||"low").toLowerCase(),sevClass=sev==="critical"?"crit":sev==="medium"?"med":sev;return `<div class="auditissue" data-sev="${esc(sev)}" style="${i.scope==="build-time"?"opacity:.72":""}"><div class="head"><span class="chip ${sevClass}"><span class="d"></span>${esc(sev)}</span><span class="chip low"><span class="d"></span>${i.scope==="build-time"?"build-time only":i.scope==="environment"?"environment / repo":i.scope==="image"?"container image":"runtime closure"}</span><span class="title">${esc(i.id||i.title||"Security issue")}</span></div>${i.title&&i.id?`<div class="u87">${esc(i.title)}</div>`:""}<div class="meta">${[i.component?`<b>${esc(i.component)}</b>`:"",i.installed?"installed "+esc(i.installed):"",i.fixed?"fixed "+esc(i.fixed):"",i.source?"scanner "+esc(i.source):"",i.score?"CVSS "+esc(i.score):"",i.disposition?esc(i.disposition):""].filter(Boolean).join(" - ")}</div>${i.evidence?`<details><summary>Show scanner evidence</summary><pre>${esc(i.evidence)}</pre></details>`:""}</div>`;}).join(""):'<div class="auditempty">No detailed records are loaded. Run the audit to generate affected packages, CVEs, versions, and scanner evidence.</div>'}</div></details></div>
 </div>`;
}
function findHTML(m){const ord={crit:0,high:1,med:2,low:3,"":4};
 const rows=FINDINGS.map((f,i)=>({f,i})).sort((a,b)=>ord[a.f.sev]-ord[b.f.sev]);
 return `<table class="ftable"><thead><tr><th>Sev</th><th>Finding</th><th>Type</th><th>Status</th><th></th></tr></thead><tbody>
   ${rows.map(({f,i})=>`<tr>
     <td><span class="chip ${f.sev||"low"}"><span class="d"></span>${SEVNAME[f.sev]||"unrated"}</span></td>
     <td class="ttl">${esc(f.title)}</td><td class="src">${esc(f.vulnType||f.src||"")}</td>
     <td><span class="chip low"><span class="d"></span>${esc(f.status)}</span></td><td><button class="btn ghost sm" data-fedit="${i}">Edit</button></td></tr>`).join("")||`<tr><td colspan="5"><div class="empty">no findings for ${esc(m.id)} yet</div></td></tr>`}</tbody></table>
   <div class="addbar"><label class="fld u10">New finding<input data-ftitle placeholder="title, then calculate CVSS severity"></label>
     <button class="btn ghost sm" data-findai>Suggest from evidence</button><button class="btn ghost sm" data-findsecrets>Collect credentials</button><button class="btn sm" data-fadd>Add &amp; edit</button></div>
   <div class="u88">Click a finding to edit it like a pwndoc vulnerability (type, CVSS, description, remediation, references, PoC with screenshots).</div>`;
}
function secretsHTML(m){const rows=SECRETS;
 return `<div class="capadd"><input data-secretlabel placeholder="Label, e.g. admin password"><select data-secretkind><option value="password">Password</option><option value="token">Token</option><option value="api-key">API key</option><option value="private-key">Private key</option><option value="wifi">Wi-Fi</option><option value="pin">PIN</option><option value="cookie">Cookie</option><option value="other">Other</option></select><input data-secretuser placeholder="Username (optional)"><input type="password" data-secretvalue placeholder="Secret value" autocomplete="new-password"><input data-secretsource placeholder="Exact source: note/capture/recording"><button class="btn sm" data-secretadd>Add secret</button><button class="btn ghost sm" data-secretai>Find with AI</button><button class="btn ghost sm" data-secretrefresh>Refresh</button></div><div class="secretwarn">Values are stored in your OS credential vault. They are excluded from project exports, notes, findings, reports, and the ordinary MCP evidence index.</div>${rows.length?`<div class="secretgrid">${rows.map(s=>`<div class="secretcard"><div><b>${esc(s.label)}</b> <span class="chip low">${esc(s.kind)}</span></div>${s.username?`<div class="u50">${esc(s.username)}</div>`:""}<div class="secretvalue" data-secretmasked="${esc(s.id)}">••••••••••••</div><div class="source">Source: ${esc(s.source)}</div>${s.note?`<div class="note">${esc(s.note)}</div>`:""}<div class="acts"><button class="btn ghost sm" data-secretcopy="${esc(s.id)}">Copy</button><button class="btn ghost sm" data-secretreveal="${esc(s.id)}">Reveal</button><button class="btn ghost sm" data-secretdelete="${esc(s.id)}">Delete</button></div></div>`).join("")}</div>`:`<div class="empty">No collected secrets for ${esc(m.id)}. Add one manually or ask the connected AI agent to search mission evidence.</div>`}`;
}
function capHTML(m){const items=CAPTURES.filter(c=>c.mission===m.id);
 const add=`<div class="capadd">
     <button class="btn sm" data-capimport>Import evidence file...</button>
     <button class="btn ghost sm" data-newtype>New type</button></div>
   <div class="typeform u13" data-typeform>
     <div class="rowf"><label class="fld u10">Type name<input data-tname placeholder="e.g. HackRF sweep"></label>
       <label class="fld u11">Extensions (comma)<input data-text placeholder="e.g. sweep, s16, dat"></label></div>
     <div><div class="u89">Icon</div><div class="iconpick" data-iconpick>${ICON_CHOICES.map((e,i)=>`<button type="button" data-ic="${e}" class="${i===0?"sel":""}">${e}</button>`).join("")}</div></div>
     <div class="rowf"><button class="btn sm" data-tsave>Save type</button><span class="u90">Files with these extensions are then auto-classified.</span></div></div>`;
 const grid=items.length?`<div class="capgrid">${items.map(c=>{const meta=Object.entries(c.meta).map(([k,v])=>`<b>${k}</b><span>${esc(v)}</span>`).join("");
   return `<div class="cap"><div class="top"><span class="ic">${typeIcon(c.type)}</span>
     <div><div class="nm">${esc(c.name)}</div><div class="ty">${esc(typeLabel(c.type))} &middot; ${esc(c.tool)}</div></div></div>
     <div class="meta">${meta}</div><div class="note">${esc(c.note)}</div>
     <div class="acts"><button class="btn sm" data-open="${esc(c.name)}" data-t="${c.type}">Open</button></div></div>`;}).join("")}</div>`
   :`<div class="empty">no captures for ${esc(m.id)} yet - add one above (IQ, Flipper, Proxmark, pcap, firmware or a custom type)</div>`;
 return add+`<section class="liveart"><div class="livearthead"><b>Live workspace artifacts</b><span class="liveartmeta">Files are listed without reading their contents.</span><span class="spacer"></span><button class="btn ghost sm" data-live-refresh>Refresh</button></div><div class="liveartrows" data-live-rows><div class="empty">Select Refresh to inventory the mission workspace.</div></div></section>`+grid;
}

/* Persistent container terminals. xterm.js is vendored, never loaded from a CDN. */
const TERM_GROUPS=new Map(),TERM_BY_SID=new Map();let terminalModules=null,terminalEventsBound=false;
async function loadTerminalModules(){return terminalModules||(terminalModules=Promise.all([import("./vendor/xterm/xterm.mjs"),import("./vendor/xterm/addon-fit.mjs")]).then(([x,f])=>({Terminal:x.Terminal,FitAddon:f.FitAddon})));}
function bindTerminalEvents(){if(terminalEventsBound||!window.runtime?.EventsOn)return;terminalEventsBound=true;
 window.runtime.EventsOn("rfswift:terminal:data",p=>queueTerminalWrite(TERM_BY_SID.get(p.id),p.data||""));
 window.runtime.EventsOn("rfswift:terminal:error",p=>{const x=TERM_BY_SID.get(p.id);if(x)x.term.writeln("\r\n\x1b[31mterminal error: "+(p.error||"unknown")+"\x1b[0m");});
 window.runtime.EventsOn("rfswift:terminal:exit",p=>{const x=TERM_BY_SID.get(p.id);if(!x)return;TERM_BY_SID.delete(p.id);x.sid="";x.recordingActive=false;if(p.recordingPath){x.recordingPath=p.recordingPath;if(!x.recordingPaths.includes(p.recordingPath))x.recordingPaths.push(p.recordingPath);}x.term.writeln("\r\n\x1b[90m[session ended]"+(p.recordingPath?" recording: "+p.recordingPath:"")+"\x1b[0m");if(x.group.agent){clearInterval(x.group.syncTimer);x.group.syncTimer=0;renderAgentTerminal(x.group);}else renderTerminalGroup(x.group);});}
function queueTerminalWrite(item,data){if(!item||!data)return;item.outputQueue=(item.outputQueue||"")+data;if(item.outputTimer)return;item.outputTimer=setTimeout(()=>{item.outputTimer=0;const chunk=item.outputQueue;item.outputQueue="";item.term.write(chunk,()=>item.term.refresh(0,item.term.rows-1));},16);}
async function terminalCopy(item){const text=item.term.getSelection();if(!text){toast("Select terminal text first");return;}try{await window.runtime.ClipboardSetText(text);toast("Terminal text copied");}catch(e){toast("Copy failed");}}
async function terminalPaste(item){if(!item.sid){toast("Connect the terminal before pasting");return;}try{const text=await window.runtime.ClipboardGetText();if(text)await B.TerminalInput(item.sid,text);}catch(e){item.term.writeln("\r\n\x1b[31mPaste failed\x1b[0m");}}
let terminalContext=null,terminalContextItem=null;
function openTerminalContext(e,item){e.preventDefault();terminalContextItem=item;if(!terminalContext){terminalContext=document.createElement("div");terminalContext.className="editorctx";terminalContext.innerHTML='<button data-tclip="copy">Copy</button><button data-tclip="paste">Paste</button><button data-tclip="select">Select all</button>';document.body.appendChild(terminalContext);terminalContext.onmousedown=ev=>{const action=ev.target.closest("button")?.dataset.tclip;if(!action)return;ev.preventDefault();if(action==="copy")terminalCopy(terminalContextItem);if(action==="paste")terminalPaste(terminalContextItem);if(action==="select")terminalContextItem.term.selectAll();terminalContext.classList.remove("open");};}terminalContext.style.left=Math.min(e.clientX,innerWidth-190)+"px";terminalContext.style.top=Math.min(e.clientY,innerHeight-45)+"px";terminalContext.classList.add("open");}
async function newTerminalItem(group,shell="/bin/zsh",record=false,recordingDir=""){const {Terminal,FitAddon}=await loadTerminalModules(),fit=new FitAddon(),term=new Terminal({cursorBlink:true,convertEol:false,scrollback:10000,fontFamily:"JetBrains Mono,ui-monospace,monospace",fontSize:13,linkHandler:{activate:(_,uri)=>B.OpenExternalURL(uri).catch(e=>toast("Open link failed: "+((e&&e.message)||e)))},theme:{background:"#07110f",foreground:"#cce4df",cursor:"#54d6c8",selectionBackground:"#24504b"}}),holder=document.createElement("div");holder.style.height="100%";term.loadAddon(fit);term.open(holder);const item={key:++group.counter,label:(shell.split("/").pop()||"shell")+" "+group.counter,shell,record,recordingDir,sid:"",recordingPath:"",recordingPaths:[],recordingActive:false,term,fit,holder,group};term.onData(data=>item.sid&&B.TerminalInput(item.sid,data).catch(e=>term.writeln("\r\n\x1b[31m"+((e&&e.message)||e)+"\x1b[0m")));term.attachCustomKeyEventHandler(e=>{if(e.type!=="keydown")return true;const key=e.key.toLowerCase(),copy=(e.metaKey&&key==="c")||(e.ctrlKey&&e.shiftKey&&key==="c"),paste=(e.metaKey&&key==="v")||(e.ctrlKey&&e.shiftKey&&key==="v");if(copy){e.preventDefault();terminalCopy(item);return false;}if(paste){e.preventDefault();terminalPaste(item);return false;}return true;});holder.oncontextmenu=e=>openTerminalContext(e,item);group.items.push(item);group.active=item.key;return item;}
function recordingNameDialog(current){return new Promise(resolve=>{aiEditResolve=resolve;$("#aiEditTitle").textContent="Rename terminal recording";$("#aiEditBody").innerHTML=`<p class="aiedit-help">Choose a recognizable evidence name. The .cast extension is added automatically.</p><label class="fld">Recording name<input id="recordingName" value="${esc(current.replace(/\.cast$/i,""))}" autocomplete="off"></label><div class="aiedit-actions"><button class="btn ghost sm" data-reccancel>Cancel</button><button class="btn sm" data-recrename>Rename</button></div>`;const input=$("#recordingName"),submit=()=>{const value=input.value.trim();if(value)closeAIEdit(value);};$("[data-reccancel]",$("#aiEditBody")).onclick=()=>closeAIEdit();$("[data-recrename]",$("#aiEditBody")).onclick=submit;input.onkeydown=e=>{if(e.key==="Enter"){e.preventDefault();submit();}};$("#aiEditModal").classList.add("open");setTimeout(()=>{input.focus();input.select();},0);});}
function addRecordingToMissionNote(group,path){const note=noteVal(group.mission),directive=":::terminal-recording "+path+" :::";if(note.includes(directive)){toast("Recording is already in the note");return;}persistNote(group.mission,note+(note.trim()?"\n\n":"")+directive+"\n");renderDock();toast("Recording added to the mission note");}
async function openRecordingDialog(mission,path,name){const layer=document.createElement("div");layer.className="modal-backdrop open recordingdialog";layer.innerHTML='<div class="modal"><div class="mhead"><h2>Terminal recording</h2><span class="spacer"></span><button class="btn ghost sm" data-rdclose>Close</button></div><div class="mbody"><div class="recordingdialogname">'+esc(name)+'</div><div class="termrecord" data-recording="'+encodeURIComponent(path)+'"><div class="termrecordbar"><button type="button" data-castplay>Play</button><button type="button" data-castrestart>Restart</button><span>'+esc(name)+'</span></div><div data-castterm></div></div></div><div class="mactions"><button class="btn ghost sm" data-rdai>Use as AI evidence</button><button class="btn sm" data-rdnote>Add to note</button></div></div>';document.body.append(layer);const close=()=>layer.remove();$("[data-rdclose]",layer).onclick=close;layer.onclick=e=>{if(e.target===layer)close();};$("[data-rdnote]",layer).onclick=()=>{addRecordingToMissionNote({mission},path);close();};$("[data-rdai]",layer).onclick=async e=>{const button=e.currentTarget;button.disabled=true;try{await B.RegisterTerminalRecordingEvidence(mission.id,name);await loadCaptures(mission.id);button.textContent="AI access approved";toast("Recording approved as AI evidence");}catch(err){toast("AI evidence failed: "+((err&&err.message)||err));}finally{button.disabled=false;}};await mountRecordingPlayers(layer);}
