const MF_DATA_ACCESS={"000":"Read A|B - Write A|B - Inc A|B - Dec/transfer/restore A|B","010":"Read A|B - Write never - Inc never - Dec/transfer/restore A|B","100":"Read A|B - Write B - Inc never - Dec/transfer/restore A|B","110":"Read A|B - Write B - Inc B - Dec/transfer/restore A|B","001":"Read A|B - Write never - Inc never - Dec/transfer/restore A|B","011":"Read B - Write B - Inc never - Dec/transfer/restore never","101":"Read B - Write never - Inc never - Dec/transfer/restore never","111":"Read never - Write never - Inc never - Dec/transfer/restore never"};
