function mifareClassicHTML(data,base=0){const full=Math.floor(data.length/16)*16,type=full>=4096?"MIFARE Classic 4K":full>=2048?"MIFARE Classic 2K":full>=1024?"MIFARE Classic 1K":"partial MIFARE Classic dump",sectors=[];let block=0,offset=0,invalid=0,defaults=0;while(offset+64<=full){const sector=sectors.length,blocks=full>=4096&&sector>=32?16:4;if(offset+blocks*16>full)break;const trailer=data.slice(offset+(blocks-1)*16,offset+blocks*16),access=mfAccess(trailer),keyA=mfHex(trailer.slice(0,6)).replace(/ /g,""),keyB=mfHex(trailer.slice(10,16)).replace(/ /g,"");if(!access.valid)invalid++;if(MF_DEFAULT_KEYS.has(keyA))defaults++;if(MF_DEFAULT_KEYS.has(keyB))defaults++;let rows="";for(let local=0;local<blocks;local++,block++){const bytes=data.slice(offset+local*16,offset+(local+1)*16),trailerBlock=local===blocks-1,group=trailerBlock?3:blocks===16?Math.min(2,Math.floor(local/5)):local,bits=access.groups[group].bits;let meaning;if(trailerBlock){meaning=`<b>Sector trailer</b><br>Key A: <span class="${MF_DEFAULT_KEYS.has(keyA)?"mfwarn":""}">${keyA}</span> - Key B/data: <span class="${MF_DEFAULT_KEYS.has(keyB)?"mfwarn":""}">${keyB}</span><div class="mfaccess"><b>C1C2C3 ${bits}</b> - ${MF_TRAILER_ACCESS[bits]}<br>User byte: 0x${trailer[9].toString(16).padStart(2,"0").toUpperCase()}</div>`;}else{const value=mfValueBlock(bytes),manufacturer=sector===0&&local===0?`Manufacturer block heuristic: UID ${mfHex(bytes.slice(0,4))} - BCC 0x${bytes[4].toString(16).padStart(2,"0").toUpperCase()} - SAK 0x${bytes[5].toString(16).padStart(2,"0").toUpperCase()} - ATQA ${mfHex(bytes.slice(6,8))}`:"Data block";meaning=`${manufacturer}${value?`<br><span class="mfok">Valid value block: ${value.value} - address ${value.address}</span>`:""}<div class="mfaccess"><b>Access group ${group}, C1C2C3 ${bits}</b> - ${MF_DATA_ACCESS[bits]}</div>`;}rows+=`<div class="mfblock ${trailerBlock?"trailer":""}"><b>Block ${block}<br><small>0x${(base+offset+local*16).toString(16)}</small></b><span class="bytes">${mfHex(bytes)}</span><span class="meaning">${meaning}${access.groups[group].valid?"":'<br><span class="mfbad">Access-bit complements are invalid</span>'}</span></div>`;}sectors.push(`<section class="mfsector"><h4>Sector ${sector}<span class="spacer"></span>${blocks} blocks - trailer block ${block-1}</h4>${rows}</section>`);offset+=blocks*16;}const remainder=data.length-offset;return`<div class="mfsummary"><b>${type}</b> - ${data.length} bytes - ${sectors.length} complete sectors - ${Math.floor(full/16)} blocks<br><span class="${invalid?"mfbad":"mfok"}">${invalid?invalid+" sector(s) have invalid access-bit complements":"All decoded access-bit complements are consistent"}</span> - <span class="${defaults?"mfwarn":""}">${defaults} known default/common sector key occurrence(s)</span>${remainder?` - ${remainder} trailing/undecoded bytes`:""}<br><small>Permissions describe authenticated card operations; recovered dump bytes alone do not prove that a key is currently accepted by the physical card.</small></div>${sectors.join("")||'<div class="mfbad">At least one complete 64-byte sector is required.</div>'}`;}
