const CHEF_OPS=[["extract","Extract range"],["hex","Decode - From Hex"],["base64","Decode - From Base64 / URL"],["base32","Decode - From Base32"],["base58","Decode - From Base58"],["ascii85","Decode - From ASCII85"],["binary","Decode - From binary bytes"],["octal","Decode - From octal bytes"],["decimal","Decode - From decimal bytes"],["url","Decode - URL"],["quoted","Decode - Quoted-printable"],["html","Decode - HTML entities"],["json","Decode - JSON string"],["utf16le","Decode - UTF-16LE to UTF-8"],["utf16be","Decode - UTF-16BE to UTF-8"],["tohex","Encode - To Hex"],["tobase64","Encode - To Base64"],["tobase64url","Encode - To Base64URL"],["tobase32","Encode - To Base32"],["tobase58","Encode - To Base58"],["toascii85","Encode - To ASCII85"],["tobinary","Encode - To binary bytes"],["tooctal","Encode - To octal bytes"],["todecimal","Encode - To decimal bytes"],["tourl","Encode - URL"],["toquoted","Encode - Quoted-printable"],["tohtml","Encode - HTML entities"],["tojson","Encode - JSON string"],["toutf16le","Encode - UTF-8 to UTF-16LE"],["toutf16be","Encode - UTF-8 to UTF-16BE"],["xor","Transform - XOR key"],["add","Transform - Add to each byte"],["rotate","Transform - Rotate each byte"],["swap16","Transform - Swap 16-bit endian"],["swap32","Transform - Swap 32-bit endian"],["stripnull","Transform - Strip null bytes"],["reverse","Transform - Reverse bytes"],["rot13","Transform - ROT13"],["gzip","Decompress - Gzip"],["deflate","Decompress - Zlib"],["deflate-raw","Decompress - Raw deflate"],["togzip","Compress - Gzip"],["todeflate","Compress - Zlib"],["todeflate-raw","Compress - Raw deflate"]];
