function renderChefSteps(){const root=$("#artifactChefSteps");root.innerHTML=CHEF_STEPS.map((s,i)=>`<div class="chefstep" data-chefstep="${i}"><select data-chefop>${CHEF_OPS.map(o=>`<option value="${o[0]}" ${o[0]===s.op?"selected":""}>${o[1]}</option>`).join("")}</select><input data-chefoffset value="${chefAttr(s.offset)}" placeholder="offset: 0 / 0x10"><input data-cheflength value="${chefAttr(s.length)}" placeholder="length: all"><input data-chefparam value="${chefAttr(s.param)}" placeholder="parameter / XOR key"><span class="acts"><button class="btn ghost sm" data-chefup title="Move up">↑</button><button class="btn ghost sm" data-chefdown title="Move down">↓</button><button class="btn ghost sm" data-chefremove title="Remove">×</button></span></div>`).join("");$$('[data-chefstep]',root).forEach(row=>{const i=+row.dataset.chefstep,save=()=>{CHEF_STEPS[i]={op:$("[data-chefop]",row).value,offset:$("[data-chefoffset]",row).value,length:$("[data-cheflength]",row).value,param:$("[data-chefparam]",row).value};};$$('select,input',row).forEach(x=>x.onchange=save);$("[data-chefup]",row).onclick=()=>{save();if(i){[CHEF_STEPS[i-1],CHEF_STEPS[i]]=[CHEF_STEPS[i],CHEF_STEPS[i-1]];renderChefSteps();}};$("[data-chefdown]",row).onclick=()=>{save();if(i<CHEF_STEPS.length-1){[CHEF_STEPS[i+1],CHEF_STEPS[i]]=[CHEF_STEPS[i],CHEF_STEPS[i+1]];renderChefSteps();}};$("[data-chefremove]",row).onclick=()=>{CHEF_STEPS.splice(i,1);renderChefSteps();};});}
