function chefBase32(value,index){const alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZ234567",clean=value.toUpperCase().replace(/[\s=-]/g,"");let bits=0,acc=0,out=[];for(const c of clean){const n=alphabet.indexOf(c);if(n<0)throw new Error(`Decoder ${index+1}: invalid Base32 character ${c}`);acc=(acc<<5)|n;bits+=5;if(bits>=8){bits-=8;out.push((acc>>bits)&255);}}return Uint8Array.from(out);}
