function chefAscii85(value,index){let clean=value.trim().replace(/^<~/," ").replace(/~>$/,"").replace(/\s/g,""),out=[];for(let i=0;i<clean.length;){if(clean[i]==="z"){out.push(0,0,0,0);i++;continue;}const chunk=clean.slice(i,i+5),count=chunk.length;if(count===1)throw new Error(`Decoder ${index+1}: invalid ASCII85 tail`);let n=0;for(const c of chunk.padEnd(5,"u")){const v=c.charCodeAt(0)-33;if(v<0||v>84)throw new Error(`Decoder ${index+1}: invalid ASCII85 character`);n=n*85+v;}const bytes=[Math.floor(n/16777216)%256,Math.floor(n/65536)%256,Math.floor(n/256)%256,n%256];out.push(...bytes.slice(0,count-1));i+=5;}return Uint8Array.from(out);}
function chefNumberBytes(value,radix,index){const tokens=value.trim().split(/[\s,;:|]+/).filter(Boolean),out=tokens.map(x=>parseInt(x.replace(/^0[bxo]/i,""),radix));if(out.some(x=>!Number.isInteger(x)||x<0||x>255))throw new Error(`Decoder ${index+1}: values must be bytes in base ${radix}`);return Uint8Array.from(out);}
