function chefToBase32(data){const alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";let bits=0,acc=0,out="";for(const byte of data){acc=(acc<<8)|byte;bits+=8;while(bits>=5){bits-=5;out+=alphabet[(acc>>bits)&31];}}if(bits)out+=alphabet[(acc<<(5-bits))&31];return out.padEnd(Math.ceil(out.length/8)*8,"=");}
