async function runChefStack(){let data=chefRange().bytes;for(let i=0;i<CHEF_STEPS.length;i++)data=await applyChefStep(data,CHEF_STEPS[i],i);const view=$("#artifactChefView").value,mf=$("#artifactChefMifare"),plain=$("#artifactChefData"),card=view==="mifare"||view==="mifareul";mf.classList.toggle("show",card);plain.style.display=card?"none":"block";if(view==="mifare")mf.innerHTML=mifareClassicHTML(data,0);else if(view==="mifareul")mf.innerHTML=mifareUltralightHTML(data,0);else plain.value=view==="hex"?chefHex(data,0):view==="base64"?bytesToB64(data):view==="strings"?(new TextDecoder("latin1").decode(data).match(/[\x20-\x7e]{4,}/g)||[]).join("\n"):new TextDecoder().decode(data);$("#artifactChefMeta").textContent=`Stack result - ${CHEF_STEPS.length} operation(s) - ${artifactSize(data.length)}`;return data;}
async function openArtifactDecoder(m,path){const p=await B.PreviewWorkspaceArtifact(m.id,path);CHEF_BYTES=p.kind==="binary"?bytesFromB64(p.content):new TextEncoder().encode(p.content||"");CHEF_TRUNCATED=!!p.truncated;CHEF_STEPS=[];renderChefSteps();$("#artifactChefPath").textContent=m.id+" /workspace/"+path;$("#artifactChefStart").value="0";$("#artifactChefLength").value="";$("#artifactChefView").value=p.kind==="binary"?"hex":"text";renderChefRange();$("#artifactChefModal").classList.add("open");}
async function cyberChefPrivateURL(bytes){const base=await B.CyberChefURL();if(!/^http:\/\/127\.0\.0\.1:\d+\/[0-9a-f]{48}\/$/.test(base))throw new Error("Workbench returned an invalid private CyberChef endpoint");return base+"CyberChef_v11.4.0.html#recipe=&input="+encodeURIComponent(bytesToB64(bytes));}
$("#artifactChefAddStep").onclick=()=>{CHEF_STEPS.push({op:"extract",offset:"0",length:"",param:""});renderChefSteps();};$("#artifactChefRun").onclick=async()=>{try{await runChefStack();}catch(e){toast((e&&e.message)||e,"error");}};$("#artifactChefApply").onclick=()=>{try{renderChefRange();}catch(e){toast((e&&e.message)||e,"error");}};$("#artifactChefView").onchange=()=>$("#artifactChefApply").click();$("#artifactChefBrowser").onclick=async()=>{try{const range=chefRange();if(!range.bytes.length)throw new Error("The selected byte range is empty");await B.OpenExternalURL(await cyberChefPrivateURL(range.bytes));toast("Opened selected range in CyberChef","success");}catch(e){toast((e&&e.message)||e,"error");}};$("#artifactChefExpand").onclick=()=>$("#artifactChefModal").classList.toggle("full");$("#artifactChefClose").onclick=()=>$("#artifactChefModal").classList.remove("open","full");
function renderLiveArtifacts(m){const host=$("[data-live-rows]");if(!host)return;const items=LIVE_ARTIFACTS.get(m.id)||[];host.innerHTML=items.length?items.map(a=>{const p=encodeURIComponent(a.path),registered=a.registered?'<span class="chip ok"><span class="d"></span>registered</span>':'',ai=a.aiAllowed?'<span class="chip med"><span class="d"></span>AI content</span>':'';return `<div class="liveartrow"><div><div class="liveartpath" title="${esc(a.path)}">${esc(a.path)}</div><div class="liveartmeta">${esc(typeLabel(a.type))} - ${artifactSize(a.size)} - ${esc(a.modified||"")} ${registered} ${ai}</div></div><span class="ic">${typeIcon(a.type)}</span><div class="liveartacts"><button class="btn ghost sm" data-live-preview="${p}">Inspect / decode</button>${a.registered?`<button class="btn ghost sm" data-live-ai="${p}" data-live-name="${encodeURIComponent(a.name)}">${a.aiAllowed?"Revoke AI":"Allow AI content"}</button>`:`<button class="btn sm" data-live-register="${p}">Register</button><button class="btn ghost sm" data-live-note="${p}">Add to note</button>`}</div></div>`;}).join(""):'<div class="empty">No files found in the live mission workspace.</div>';wireLiveArtifactButtons(m);}
async function refreshLiveArtifacts(m){const host=$("[data-live-rows]");if(host)host.innerHTML='<div class="empty">Inventorying workspace...</div>';try{LIVE_ARTIFACTS.set(m.id,(await B.ListWorkspaceArtifacts(m.id))||[]);renderLiveArtifacts(m);}catch(e){if(host)host.innerHTML='<div class="empty">Workspace inventory unavailable: '+esc((e&&e.message)||e)+'</div>';}}
