/* ---------- optional AI assistant (off by default) ---------- */
const SPARK='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" class="u3"><path d="M12 3l1.9 4.6L18.5 9l-4.6 1.4L12 15l-1.9-4.6L5.5 9l4.6-1.4z"/></svg>';
const AGENTLABEL={codex:"Codex CLI",claude:"Claude Code",kimi:"Kimi Code",glm:"GLM / Z.ai CLI"};
let backendAICfg=null,agentClients=[];
function aiCfg(){const def={enabled:false,client:"codex",allowWrite:false,allowExec:false,yolo:{}};if(backendAICfg)return Object.assign(def,backendAICfg);try{return Object.assign(def,JSON.parse(store.get("agentcfg","{}")));}catch(e){return def;}}
function setAiCfg(c){backendAICfg=c;if(online)return B.SetAgentCfg(c);store.set("agentcfg",JSON.stringify(c));return Promise.resolve();}
function aiTag(){const c=aiCfg();return AGENTLABEL[c.client]||c.client||"coding agent";}
function renderAIChip(){const c=aiCfg(),b=$("#aiBtn");b.innerHTML=SPARK+" "+(c.enabled?aiTag():"Agent");b.style.color=c.enabled?"var(--accent)":"";b.style.borderColor=c.enabled?"var(--accent)":"";}
function renderAIBody(){const c=aiCfg(),clients=agentClients.length?agentClients:Object.keys(AGENTLABEL).map(id=>({id,label:AGENTLABEL[id],available:false}));$("#aiBody").innerHTML=`
   <label class="u117"><input type="checkbox" id="aiOn" ${c.enabled?"checked":""} class="u118"> Enable mission-scoped MCP bridge</label>
   <div class="u119">RF Swift makes no model API requests and stores no model keys. The selected external CLI handles its own login or subscription and connects to the Workbench through local stdio MCP.</div>
   <label class="fld">Coding-agent CLI<select id="aiProv">${clients.map(x=>`<option value="${esc(x.id)}" ${c.client===x.id?"selected":""}>${esc(x.label)}${x.available?" - installed":" - not found"}</option>`).join("")}</select></label>
   <div class="card u120"><div class="cardhead"><h3>MCP permissions</h3><span class="chip ${c.allowExec?"high":"ok"}"><span class="d"></span>${c.allowExec?"command access":(c.allowWrite?"workspace write":"read only")}</span></div><div class="u121">
     <label><input type="checkbox" id="aiWrite" ${c.allowWrite?"checked":""}> Allow updating notes and findings</label>
     <label><input type="checkbox" id="aiExec" ${c.allowExec?"checked":""}> Allow executing commands inside the selected mission</label>
     <label><input type="checkbox" id="aiYolo" ${(c.yolo||{})[c.client]?"checked":""}> YOLO mode for this coding-agent CLI</label>
     <div class="u122"><b>Warning:</b> YOLO mode disables the selected CLI's confirmation prompts and may also disable its sandbox. It does not expand RF Swift MCP permissions, but enabled command access can still affect the mission target.</div>
     <div class="u123">Disabled by default. Each MCP process is restricted to the mission used when it is launched. Command execution is advertised to the client only when explicitly enabled.</div></div></div>
   <button class="btn" id="aiSave">Save MCP settings</button>`;
  const yolo=Object.assign({},c.yolo||{}),provider=$("#aiProv"),yoloBox=$("#aiYolo");provider.onchange=()=>{yoloBox.checked=!!yolo[provider.value];};yoloBox.onchange=()=>{yolo[provider.value]=yoloBox.checked;};
  $("#aiSave").onclick=()=>{yolo[provider.value]=yoloBox.checked;const nc={enabled:$("#aiOn").checked,client:provider.value,allowWrite:$("#aiWrite").checked,allowExec:$("#aiExec").checked,yolo};setAiCfg(nc).then(()=>{renderAIChip();$("#aiModal").classList.remove("open");renderDock();toast(nc.enabled?(aiTag()+" MCP bridge enabled"):"MCP bridge disabled");}).catch(e=>toast("Agent settings failed: "+((e&&e.message)||e)));};
}
