/* ---------- media helpers ---------- */
function pickImage(cb){const inp=document.createElement("input");inp.type="file";inp.accept="image/*";
  inp.onchange=()=>{const f=inp.files&&inp.files[0];if(!f)return;const r=new FileReader();r.onload=()=>cb(r.result,f.name);r.readAsDataURL(f);};inp.click();}
async function storeNoteImage(dataURL,name="image"){if(!online)return{path:dataURL,dataURL};return B.SaveNoteImage(curMission,name,dataURL);}
function insertAtCursor(ta,text){const s=(ta.selectionStart!=null?ta.selectionStart:ta.value.length);const e=(ta.selectionEnd!=null?ta.selectionEnd:ta.value.length);
  ta.value=ta.value.slice(0,s)+text+ta.value.slice(e);ta.selectionStart=ta.selectionEnd=s+text.length;}

/* ---------- finding editor (pwndoc-style vulnerability) ---------- */
const FSTAT=["draft","open","confirmed","in progress","remediated","risk accepted","false positive"];
const CVSS_METRICS=[
 ["AV","Attack vector",[["N","Network"],["A","Adjacent"],["L","Local"],["P","Physical"]]],
 ["AC","Attack complexity",[["L","Low"],["H","High"]]],
 ["PR","Privileges required",[["N","None"],["L","Low"],["H","High"]]],
 ["UI","User interaction",[["N","None"],["R","Required"]]],
 ["S","Scope",[["U","Unchanged"],["C","Changed"]]],
 ["C","Confidentiality",[["N","None"],["L","Low"],["H","High"]]],
 ["I","Integrity",[["N","None"],["L","Low"],["H","High"]]],
 ["A","Availability",[["N","None"],["L","Low"],["H","High"]]]
];
function parseCVSS(v){const out={AV:"N",AC:"L",PR:"N",UI:"N",S:"U",C:"N",I:"N",A:"N"};String(v||"").split("/").slice(1).forEach(x=>{const p=x.split(":");if(Object.prototype.hasOwnProperty.call(out,p[0]))out[p[0]]=p[1];});return out;}
function cvssVector(m){return "CVSS:3.1/"+CVSS_METRICS.map(x=>x[0]+":"+m[x[0]]).join("/");}
function cvssRound(n){return Math.ceil((n-1e-10)*10)/10;}
function cvssScore(m){const av={N:.85,A:.62,L:.55,P:.2}[m.AV],ac={L:.77,H:.44}[m.AC],ui={N:.85,R:.62}[m.UI],scope=m.S==="C";
 const pr=(scope?{N:.85,L:.68,H:.5}:{N:.85,L:.62,H:.27})[m.PR],impactW={N:0,L:.22,H:.56};
 const isc=1-(1-impactW[m.C])*(1-impactW[m.I])*(1-impactW[m.A]);let impact=scope?7.52*(isc-.029)-3.25*Math.pow(isc-.02,15):6.42*isc;
 if(impact<=0)return 0;const exploit=8.22*av*ac*pr*ui;return cvssRound(Math.min(scope?1.08*(impact+exploit):impact+exploit,10));}
function cvssSeverity(score){return score>=9?"crit":score>=7?"high":score>=4?"med":score>0?"low":"";}
function cvssSeverityLabel(score){const s=cvssSeverity(score);return s?SEVNAME[s]:"Not rated";}
let editIdx=-1,editMission="";
function ensureFindingFields(f){const raw=String(f.sev||"").toLowerCase();f.sev=raw.startsWith("crit")?"crit":raw.startsWith("high")?"high":raw.startsWith("med")?"med":raw.startsWith("low")?"low":cvssSeverity(cvssScore(parseCVSS(f.cvss)));f.vulnType=f.vulnType||"";f.cvss=f.cvss||CVSS[f.sev]||"";f.cvssv4=f.cvssv4||"";f.description=f.description||f.title||"";f.observation=f.observation||"";f.remediation=f.remediation||"";f.references=(f.references!=null?f.references:(f.src||""));f.poc=f.poc||"";f.category=f.category||"RF Swift";f.priority=f.priority||({crit:4,high:3,med:2,low:1}[f.sev]||1);f.remediationComplexity=f.remediationComplexity||2;f.retestStatus=f.retestStatus||"unknown";f.retestDescription=f.retestDescription||"";f.paragraphs=f.paragraphs||[];f.customFields=f.customFields||[];return f;}
function richFindingField(id,label,value,rows=3){return `<div class="fld u18"><span>${label} <button class="btn ghost sm" type="button" data-rich-toggle="${id}">Rendered / WYSIWYG</button></span><textarea id="${id}" rows="${rows}">${esc(value)}</textarea><div id="${id}_tools" class="u13">${formatToolbar(id+"_rich")}</div><div id="${id}_rich" class="rendered" data-rich-editor="${id}" contenteditable="true" spellcheck="true" style="display:none;min-height:${Math.max(90,rows*28)}px;border:1px solid var(--line);border-radius:0 0 8px 8px;background:var(--panel-2)"></div></div>`;}
function richFindingValue(id){const src=$("#"+id),rich=$("#"+id+"_rich");if(rich&&rich.style.display!=="none")src.value=renderedToMarkdown(rich);return src.value;}
function openFindEditor(idx,missionID=curMission){if(!FINDINGS[idx]){toast("Finding is no longer available");return;}editIdx=idx;editMission=missionID;ensureFindingFields(FINDINGS[idx]);renderFindEditor();$("#findModal").classList.add("open");}
function renderFindEditor(){const f=FINDINGS[editIdx];if(!f)return;
  const cvm=parseCVSS(f.cvss),score=cvssScore(cvm);
  $("#findBody").innerHTML=`
   <div class="u9">
     <label class="fld u124">Title<input id="ef_title" value="${esc(f.title)}"></label>
     <label class="fld">Severity (calculated)<input id="ef_sev_label" readonly value="${cvssSeverityLabel(score)}"><input id="ef_sev" type="hidden" value="${cvssSeverity(score)}"></label></div>
   <div class="u12">
     <label class="fld u125">Vulnerability type<input id="ef_vt" value="${esc(f.vulnType)}" placeholder="e.g. Replay / fixed code"></label>
     <label class="fld u126">Affected / scope<input id="ef_target" value="${esc(f.target)}"></label>
     <label class="fld">Status<select id="ef_status">${FSTAT.map(s=>`<option ${f.status===s?"selected":""}>${s}</option>`).join("")}</select></label></div>
   <div class="u127">
    <div class="u128"><b>CVSS v3.1 base score</b><span id="ef_cvssscore" class="chip ${cvssSeverity(score)||"low"}"><span class="d"></span>${score.toFixed(1)} - ${cvssSeverityLabel(score)}</span></div>
    <div class="u129">${CVSS_METRICS.map(([key,label,opts])=>`<label class="fld">${label}<select data-cvss="${key}">${opts.map(([v,n])=>`<option value="${v}" ${cvm[key]===v?"selected":""}>${n}</option>`).join("")}</select></label>`).join("")}</div>
    <label class="fld u29">Generated vector<input id="ef_cvss" class="mono" value="${esc(cvssVector(cvm))}" aria-label="CVSS vector"></label>
   </div>
   <div class="u12">
    <label class="fld u130">pwndoc category<input id="ef_category" value="${esc(f.category)}"></label>
    <label class="fld">Priority<select id="ef_priority">${[[1,"Low"],[2,"Medium"],[3,"High"],[4,"Urgent"]].map(x=>`<option value="${x[0]}" ${f.priority===x[0]?"selected":""}>${x[1]}</option>`).join("")}</select></label>
    <label class="fld">Remediation complexity<select id="ef_remcomplex">${[[1,"Low"],[2,"Medium"],[3,"High"]].map(x=>`<option value="${x[0]}" ${f.remediationComplexity===x[0]?"selected":""}>${x[1]}</option>`).join("")}</select></label>
   </div>
   <label class="fld u18">CVSS v4 vector <span class="u19">(optional pwndoc scoring method)</span><input id="ef_cvssv4" class="mono" value="${esc(f.cvssv4)}" placeholder="CVSS:4.0/..."></label>
   ${richFindingField("ef_desc","Description",f.description,3)}
   ${richFindingField("ef_obs","Observation",f.observation,2)}
   ${richFindingField("ef_rem","Remediation",f.remediation,2)}
   <label class="fld u18">References <span class="u19">(one per line)</span><textarea id="ef_ref" rows="2">${esc(f.references)}</textarea></label>
   ${richFindingField("ef_poc",'Proof of concept <button class="btn ghost sm" id="ef_pocimg" type="button">Attach image</button>',f.poc,3)}
   <div class="u12"><label class="fld">Retest status<select id="ef_retest">${["unknown","ok","ko","partial"].map(x=>`<option ${f.retestStatus===x?"selected":""}>${x}</option>`).join("")}</select></label><label class="fld u10">Retest description<textarea id="ef_retestdesc" rows="2">${esc(f.retestDescription)}</textarea></label></div>
   <details class="u18"><summary>Advanced pwndoc fields</summary><label class="fld u42">Paragraphs JSON<textarea id="ef_paragraphs" class="mono" rows="3">${esc(JSON.stringify(f.paragraphs,null,2))}</textarea></label><label class="fld u42">Custom fields JSON<textarea id="ef_customfields" class="mono" rows="3">${esc(JSON.stringify(f.customFields,null,2))}</textarea></label></details>
   <div class="u131"><button class="btn" id="ef_save">Save</button><button class="btn ghost" id="ef_del">Delete</button><div class="u10"></div><span class="u132">Fields map to a pwndoc vulnerability.</span></div>`;
  const syncCVSS=()=>{const m={};$$('[data-cvss]').forEach(s=>m[s.dataset.cvss]=s.value);const score=cvssScore(m),sev=cvssSeverity(score);$("#ef_cvss").value=cvssVector(m);const badge=$("#ef_cvssscore");badge.className="chip "+(sev||"low");badge.innerHTML='<span class="d"></span>'+score.toFixed(1)+' - '+cvssSeverityLabel(score);$("#ef_sev").value=sev;$("#ef_sev_label").value=cvssSeverityLabel(score);};
  $$('[data-cvss]').forEach(s=>s.onchange=syncCVSS);
  $("#ef_cvss").onchange=()=>{const m=parseCVSS($("#ef_cvss").value);$$('[data-cvss]').forEach(s=>s.value=m[s.dataset.cvss]);syncCVSS();};
  $$('[data-rich-toggle]').forEach(btn=>btn.onclick=()=>{const id=btn.dataset.richToggle,src=$("#"+id),rich=$("#"+id+"_rich"),tools=$("#"+id+"_tools"),show=rich.style.display==="none";if(show){rich.innerHTML=md(src.value);rich.style.display="block";tools.style.display="block";src.style.display="none";btn.textContent="Markdown source";wireFormatToolbar($("#findBody"));rich.focus();}else{src.value=renderedToMarkdown(rich);rich.style.display="none";tools.style.display="none";src.style.display="block";btn.textContent="Rendered / WYSIWYG";src.focus();}});
  const pi=$("#ef_pocimg");if(pi)pi.onclick=()=>pickImage(d=>{const ta=$("#ef_poc"),rich=$("#ef_poc_rich");if(rich&&rich.style.display!=="none")ta.value=renderedToMarkdown(rich);insertAtCursor(ta,(ta.value?"\n":"")+"![screenshot]("+d+")\n");if(rich&&rich.style.display!=="none")rich.innerHTML=md(ta.value);});
  const pocTa=$("#ef_poc");if(pocTa)pocTa.addEventListener("paste",e=>pasteImageInto(e,pocTa));
  $("#ef_save").onclick=()=>{if(!$("#ef_sev").value){toast("Complete CVSS impact metrics before saving");return;}let paragraphs,customFields;try{paragraphs=JSON.parse($("#ef_paragraphs").value||"[]");customFields=JSON.parse($("#ef_customfields").value||"[]");if(!Array.isArray(paragraphs)||!Array.isArray(customFields))throw new Error();}catch(e){toast("Paragraphs and custom fields must be JSON arrays");return;}f.title=$("#ef_title").value.trim()||f.title;f.sev=$("#ef_sev").value;f.vulnType=$("#ef_vt").value.trim();f.target=$("#ef_target").value.trim()||"-";f.status=$("#ef_status").value;f.cvss=$("#ef_cvss").value.trim();f.cvssv4=$("#ef_cvssv4").value.trim();f.category=$("#ef_category").value.trim();f.priority=+$("#ef_priority").value;f.remediationComplexity=+$("#ef_remcomplex").value;f.description=richFindingValue("ef_desc");f.observation=richFindingValue("ef_obs");f.remediation=richFindingValue("ef_rem");f.references=$("#ef_ref").value;f.poc=richFindingValue("ef_poc");f.retestStatus=$("#ef_retest").value;f.retestDescription=$("#ef_retestdesc").value;f.paragraphs=paragraphs;f.customFields=customFields;
    if(online){B.SaveFinding(editMission,f).then(()=>loadFindings(editMission)).then(()=>{$("#findModal").classList.remove("open");renderDock();toast("Finding saved");}).catch(e=>toast("Save failed: "+((e&&e.message)||e)));return;}
    $("#findModal").classList.remove("open");renderDock();toast("Finding saved");};
  $("#ef_del").onclick=()=>{if(online&&f.id){B.DeleteFinding(editMission,f.id).then(()=>loadFindings(editMission)).then(()=>{$("#findModal").classList.remove("open");renderDock();toast("Finding deleted");}).catch(e=>toast("Delete failed: "+((e&&e.message)||e)));return;}FINDINGS.splice(editIdx,1);$("#findModal").classList.remove("open");renderDock();toast("Finding deleted");};
}
function clipboardImagePath(e){const data=e.clipboardData;if(!data)return"";const payloads=[data.getData("x-special/nautilus-clipboard"),data.getData("public.file-url"),data.getData("text/uri-list"),data.getData("text/plain")].filter(Boolean);for(const payload of payloads){const markdown=payload.match(/\((file:\/\/[^)]+\.(?:png|jpe?g|gif|webp))\)/i);if(markdown)return markdown[1];const lines=payload.trim().split(/\r?\n/).map(x=>x.trim()).filter(x=>x&&!x.startsWith("#")&&!/^(x-special\/nautilus-clipboard|copy|cut)$/i.test(x));const path=lines.find(x=>/^(file:\/\/|[A-Za-z]:[\\/]|\/).+\.(png|jpe?g|gif|webp)$/i.test(x));if(path)return path;}return"";}
function clipboardImageFile(e){const data=e.clipboardData;if(!data)return null;const files=[...(data.files||[])],items=[...(data.items||[])];return files.find(f=>f.type?.startsWith("image/")||/\.(png|jpe?g|gif|webp)$/i.test(f.name||""))||items.map(x=>x.kind==="file"?x.getAsFile():null).find(f=>f&&(f.type?.startsWith("image/")||/\.(png|jpe?g|gif|webp)$/i.test(f.name||"")))||null;}
function pasteImageInto(e,ta,done){const file=clipboardImageFile(e),path=clipboardImagePath(e);if(!file&&!path)return;e.preventDefault();e.stopPropagation();if(path&&!file){B.ImportNoteImage(curMission,path).then(saved=>{insertAtCursor(ta,(ta.value.trim()?"\n\n":"")+"![pasted]("+saved.path+")\n\n");if(done)done();}).catch(err=>toast("Image path import failed: "+((err&&err.message)||err)));return;}const r=new FileReader();r.onload=async()=>{try{const saved=await storeNoteImage(r.result,file.name||"pasted");insertAtCursor(ta,(ta.value.trim()?"\n\n":"")+"![pasted]("+saved.path+")\n\n");if(done)done();}catch(err){toast("Image paste failed: "+((err&&err.message)||err));}};r.readAsDataURL(file);}
