/* ---------- backend bridge (Wails bindings; graceful mock fallback) ---------- */
// Wails injects window.go asynchronously, so detect it (and re-detect on a short
// poll) rather than snapshotting once - otherwise the app locks into mock mode.
let B=null, online=false;
let MISSION_TEMPLATES=[];
let CONTAINER_PROFILES=[],CONTAINER_DEFAULTS=null;
let pullEventsBound=false,pullLayers={},pullDisplayedPct=0;
function resetPullProgress(){pullLayers={};pullDisplayedPct=0;$("#cm_pullbar").style.width="0";$("#cm_pullstatus").textContent="";$("#cm_pullwrap").style.display="none";}
function bindPullEvents(){if(pullEventsBound||!window.runtime||!window.runtime.EventsOn)return;pullEventsBound=true;window.runtime.EventsOn("rfswift:image-pull",p=>{const wrap=$("#cm_pullwrap"),bar=$("#cm_pullbar"),status=$("#cm_pullstatus");wrap.style.display="block";if(p.layer)pullLayers[p.layer]={current:p.current||0,total:p.total||0,status:p.status||""};const layers=Object.values(pullLayers),known=layers.filter(x=>x.total>0),current=known.reduce((n,x)=>n+x.current,0),total=known.reduce((n,x)=>n+x.total,0),done=layers.filter(x=>/complete|pull complete|already exists/i.test(x.status)).length,raw=total>0?Math.round(current*100/total):0;pullDisplayedPct=Math.max(pullDisplayedPct,Math.min(95,raw));bar.style.width=pullDisplayedPct+"%";status.textContent="Downloading - "+done+"/"+layers.length+" layers complete"+(total>0?" - "+Math.round(current/1048576)+" / "+Math.round(total/1048576)+" MB":"");});}
let auditEventsBound=false;function bindAuditEvents(){if(auditEventsBound||!window.runtime||!window.runtime.EventsOn)return;auditEventsBound=true;window.runtime.EventsOn("rfswift:audit-progress",p=>{if(!p||p.mission!==curMission)return;const wrap=$("[data-auditprogress]"),fill=$("[data-auditfill]"),stage=$("[data-auditstage]");if(wrap)wrap.classList.add("open");if(fill)fill.style.width=Math.max(0,Math.min(100,p.percent||0))+"%";if(stage)stage.textContent=(p.stage||"Auditing")+" - "+(p.percent||0)+"%";});}
let transferEventsBound=false;function humanTransferBytes(n){n=Number(n)||0;if(n<1048576)return Math.round(n/1024)+" KiB";return (n/1048576).toFixed(n<10485760?1:0)+" MiB";}
function openTransferProgress(operation,kind,target){$("#transferTitle").textContent=(operation==="import"?"Importing ":"Exporting ")+(kind==="nix"?"Nix environment":"container");$("#transferTarget").textContent=target;$("#transferStage").textContent="Choose an archive location...";$("#transferAmount").textContent="0%";$("#transferFill").classList.remove("indeterminate");$("#transferFill").style.width="0%";$("#transferClose").disabled=true;$("#transferModal").classList.add("open");}
function failTransferProgress(error){$("#transferStage").textContent="Transfer failed: "+((error&&error.message)||error);$("#transferFill").classList.remove("indeterminate");$("#transferFill").style.width="100%";$("#transferAmount").textContent="Failed";$("#transferClose").disabled=false;}
function bindTransferEvents(){if(transferEventsBound||!window.runtime?.EventsOn)return;transferEventsBound=true;window.runtime.EventsOn("rfswift:transfer-progress",p=>{if(!p)return;const percent=Math.max(0,Math.min(100,Number(p.percent)||0)),failed=/failed:/i.test(p.stage||""),fill=$("#transferFill"),amount=$("#transferAmount");$("#transferTitle").textContent=(p.operation==="import"?"Importing ":"Exporting ")+(p.kind==="nix"?"Nix environment":"container");$("#transferTarget").textContent=p.target||"RF Swift archive";$("#transferStage").textContent=p.stage||"Transferring archive";fill.style.width=(failed?100:percent)+"%";fill.classList.toggle("indeterminate",!failed&&percent>0&&percent<100&&!p.total&&p.kind==="container");amount.textContent=p.bytes?(humanTransferBytes(p.bytes)+(p.total?" / "+humanTransferBytes(p.total):"")):percent+"%";if(percent===100||failed){fill.classList.remove("indeterminate");$("#transferClose").disabled=false;}});}
let operationEventsBound=false,operationPercent={};
function renderOperationProgress(operation,target,percent,stage){const installer=operation==="package-install";if(installer&&installerMission?.id!==target)return;if(!installer&&activeCreationName&&activeCreationName!==target)return;const wrap=$(installer?"#installerProgress":"#cm_progress"),fill=$(installer?"#installerProgressFill":"#cm_progressfill"),label=$(installer?"#installerProgressStage":"#cm_progressstage"),amount=$(installer?"#installerProgressAmount":"#cm_progressamount"),key=operation+":"+target;percent=Math.max(operationPercent[key]||0,Math.max(0,Math.min(100,Number(percent)||0)));operationPercent[key]=percent;wrap.style.display="block";fill.classList.toggle("indeterminate",percent>0&&percent<100);fill.style.width=percent+"%";label.textContent=stage||"Working...";amount.textContent=percent+"%";if(percent===100)fill.classList.remove("indeterminate");}
function bindOperationEvents(){if(operationEventsBound||!window.runtime?.EventsOn)return;operationEventsBound=true;window.runtime.EventsOn("rfswift:operation-progress",p=>{if(p)renderOperationProgress(p.operation,p.target,p.percent,p.stage);});
  window.runtime.EventsOn("rfswift:nix-wsl-setup",p=>{const out=$("[data-nixsetupout]");if(out&&p&&p.line){out.textContent+=p.line+"\n";out.scrollTop=out.scrollHeight;}});}
$("#transferClose").onclick=()=>$("#transferModal").classList.remove("open");
function detectBackend(){const app=window.go?.workbench?.App||window.go?.main?.App;if(app){B=app;online=true;bindPullEvents();bindAuditEvents();bindTransferEvents();bindOperationEvents();return true;}return false;}
detectBackend();
function _rerender(){renderRail();renderMissionBar();renderDock();}
let NIX_OK=true,HOST_OS="";
function applyHostOS(){if(HOST_OS==="windows"){const h=$("#cm_usbhint");if(h)h.textContent="Forward host USB devices (SDR, Proxmark...) into WSL 2 with usbipd so Docker/Podman containers and Nix environments can reach them under /dev/bus/usb.";const ar=$("#cm_audiorow");if(ar)ar.style.display="none";const x=$("#cm_x11hint");if(x)x.textContent="Same default as the RF-Swift CLI on Windows: WSLg provides the display (DISPLAY=:0) and sound (PULSE_SERVER=unix:/mnt/wslg/PulseServer); its /mnt/wslg tree is mounted into the container, no X server or PulseAudio install needed.";}}
function applyNixSupport(){if(NIX_OK)return;const t=$('[data-scope="nix"]');if(t)t.style.display="none";const o=$('#cm_engine option[value="nix"]');if(o)o.remove();if(targetScope==="nix")targetScope="container";}
async function hydrateBackendState(){
  try{NIX_OK=await B.NixSupported();}catch(e){NIX_OK=true;}applyNixSupport();
  try{HOST_OS=(await B.HostOS())||"";}catch(e){HOST_OS="";}applyHostOS();
  try{const version=await B.GetAppVersion();if(version)$("#appVersion").textContent="rfswift v"+version+" - Community Edition";}catch(e){console.error("GetAppVersion",e);}
  try{MISSION_TEMPLATES=await B.MissionTemplates()||[];renderMissionTemplates();}catch(e){console.error("MissionTemplates",e);}
  try{CONTAINER_DEFAULTS=await B.ContainerDefaults();CONTAINER_PROFILES=await B.ContainerProfiles()||[];renderContainerProfiles();}catch(e){console.error("Container defaults/profiles",e);}
  try{backendAICfg=await B.GetAgentCfg();agentClients=await B.AgentClients()||[];renderAIChip();}catch(e){console.error("AgentConfig",e);}
  try{const ts=await B.BuiltinCaptureTypes();for(const t of (ts||[])){const old=BUILTIN_TYPES[t.key]||{};BUILTIN_TYPES[t.key]={label:t.label,ext:t.exts||[],svg:old.svg,emoji:old.emoji};}}catch(e){console.error("BuiltinCaptureTypes",e);}
  try{const ts=await B.CustomCaptureTypes();backendCustomTypes={};for(const t of (ts||[])){backendCustomTypes[t.key]={label:t.label,ext:t.exts||[],emoji:t.icon||"📎"};}}catch(e){console.error("CustomCaptureTypes",e);}
  try{const ws=await B.CurrentWorkspace();$("#workspaceBtn").textContent="project: "+ws+" ▾";}catch(e){console.error("CurrentWorkspace",e);}
  try{const cs=await B.Connections();if(cs&&cs.length){CONNECTIONS=cs;if(!CONNECTIONS.some(c=>c.id===curConn))curConn=cs[0].id;for(const c of cs){try{const a=await B.AuditConn(c.id);CONN_AUDITS[c.id]={posture:a.posture,checks:(a.checks||[]).map(x=>({s:x.severity,l:x.label,d:x.detail,r:x.rec}))};}catch(e){console.error("AuditConn",e);}}renderConnChip();}}catch(e){console.error("Connections",e);}
}
function mapMission(g){return {id:g.id,title:g.title||g.id,engine:g.engine,env:g.env||"",flakeRef:g.flakeRef||"",up:g.status==="up",starting:g.status==="starting",image:g.image||"",user:g.user||"root",caps:g.caps||[],cgroups:g.cgroups||[],mounts:g.mounts||[],net:g.net||"",ports:(g.ports||[]).map(p=>[p.port,p.published,p.service]),desktopURL:g.desktopURL||"",environmentAudit:g.environmentAudit||g.posture||{crit:0,high:0,med:0,low:0},auditIssues:g.auditIssues||[],findingSummary:g.findingSummary||{crit:0,high:0,med:0,low:0},cnote:g.notes||"",note:"",hostAudioOff:!!g.hostAudioOff,console:[],ai:[]};}
async function hydrateMissions(){try{const gs=await B.Missions();MISSIONS.length=0;(gs||[]).forEach(g=>MISSIONS.push(mapMission(g)));}catch(e){console.error("Missions",e);toast("Target refresh failed");}
  if(!mission(curMission)&&MISSIONS[0])curMission=MISSIONS[0].id;const selected=mission(curMission);if(selected){targetScope=selected.engine==="nix"?"nix":"container";$$('[data-scope]').forEach(x=>x.classList.toggle("active",x.dataset.scope===targetScope));$("#efilter").style.display=targetScope==="container"?"flex":"none";} _rerender();requestAnimationFrame(()=>$("#mList .mcard.active")?.scrollIntoView({block:"nearest"}));if(selected)selectMissionData(curMission);}
async function hydrateInspect(id){const m=mission(id);if(!m)return;try{const g=await B.InspectMission(id);if(g&&g.id){m.user=g.user||m.user;m.caps=g.caps||m.caps;m.cgroups=g.cgroups||[];m.mounts=g.mounts||m.mounts;m.net=g.net||m.net;m.image=g.image||m.image;m.env=g.env||m.env;m.desktopURL=g.desktopURL||"";m.ports=(g.ports||[]).map(p=>[p.port,p.published,p.service]);m.summary=g.summary||null;refreshImageStatus(m);}}catch(e){}}
const IMAGE_STATUS=new Map();
function refreshImageStatus(m){if(!m||m.engine==="nix"||!m.image)return;const key=m.engine+"|"+m.image,cached=IMAGE_STATUS.get(key);if(cached&&Date.now()-cached.at<600000){m.imageStatus=cached.status;return;}m.imageStatus="";B.CheckMissionImage(m.engine,m.image).then(a=>{const status=!a||!a.present?"":a.custom?"custom":a.updateAvailable?"update available":"up to date";IMAGE_STATUS.set(key,{status,at:Date.now()});m.imageStatus=status;if(curMission===m.id)renderDock();}).catch(()=>{});}
function summaryRows(m){const s=m.summary;if(!s)return "";const list=v=>(v&&v.length)?v.map(esc).join("<br>"):"none",text=v=>v?esc(v):"none",statusChip={"up to date":"ok","update available":"high","custom":"med"}[m.imageStatus||""];return `
      <tr><td>Image version</td><td class="mono">${s.imageVersion?"v"+esc(s.imageVersion):"unknown"} ${statusChip?`<span class="chip ${statusChip}"><span class="d"></span>${m.imageStatus}</span>`:""}</td></tr>
      <tr><td>Size on disk</td><td class="mono">${text(s.size)}</td></tr>
      <tr><td>Shell</td><td class="mono">${text(s.shell)}</td></tr>
      <tr><td>X display</td><td class="mono">${text(s.xDisplay)}</td></tr>
      <tr><td>Privileged</td><td class="mono">${s.privileged?'<span class="chip high"><span class="d"></span>true</span>':"false"}</td></tr>
      <tr><td>Bind mounts</td><td class="mono">${list(s.bindings)}</td></tr>
      <tr><td>Devices</td><td class="mono">${list(s.devices)}</td></tr>
      <tr><td>Extra hosts</td><td class="mono">${list(s.extraHosts)}</td></tr>
      <tr><td>Seccomp profile</td><td class="mono">${s.seccomp?esc(s.seccomp):"default"}</td></tr>
      <tr><td>Ulimits</td><td class="mono">${list(s.ulimits)}</td></tr>
      <tr><td>GPUs</td><td class="mono">${text(s.gpus)}</td></tr>`;}
function networkRows(m){const s=m.summary;if(!s)return "";const list=v=>(v&&v.length)?v.map(esc).join("<br>"):"none";return `<table class="kv">
      <tr><td>Network mode</td><td class="mono">${esc(s.networkMode||m.net)}</td></tr>${s.natSubnet?`<tr><td>NAT subnet</td><td class="mono">${esc(s.natSubnet)}</td></tr>`:""}
      <tr><td>Exposed ports</td><td class="mono">${list(s.exposedPorts)}</td></tr>
      <tr><td>Port bindings</td><td class="mono">${list(s.portBindings)}</td></tr></table>`;}
function findingCounts(){const p={crit:0,high:0,med:0,low:0};for(const f of FINDINGS){const s=f.sev==="critical"?"crit":f.sev==="medium"?"med":f.sev;if(p[s]!=null)p[s]++;}return p;}
async function loadFindings(id){try{const fs=await B.ListFindings(id);FINDINGS.length=0;(fs||[]).forEach(f=>FINDINGS.push(ensureFindingFields(f)));const m=mission(id);if(m)m.findingSummary=findingCounts();}catch(e){FINDINGS.length=0;}}
async function loadCaptures(id){try{const cs=await B.ListCaptures(id);CAPTURES.length=0;(cs||[]).forEach(c=>CAPTURES.push(c));}catch(e){CAPTURES.length=0;}}
async function loadSecrets(id){try{SECRETS=await B.ListSecrets(id)||[];}catch(e){SECRETS=[];}}
async function selectMissionData(id){if(!online)return;const m=mission(id);if(m){try{m.note=await B.GetNote(id,"note.md")||"";}catch(e){}}
  await hydrateInspect(id);await loadFindings(id);await loadCaptures(id);await loadSecrets(id);renderDock();}
function persistNote(m,v){m.note=v;if(online){B.SaveNote(m.id,"note.md",v).catch(()=>{});}else{store.set("note:"+m.id,v);}}
const _noteVal=noteVal;noteVal=function(m){return online?(m.note||""):_noteVal(m);};
const _download=download;download=function(name,content){if(online){return B.SaveFileDialog(name,content).then(p=>{toast(p?("Saved "+p):"Canceled");}).catch(()=>toast("Save failed"));}return _download(name,content);};
const _startMission=startMission;startMission=function(m){if(!online)return _startMission(m);m.starting=true;m.stopping=false;_rerender();return B.StartMission(m.id).then(()=>{m.starting=false;m.up=true;_rerender();toast("Started "+m.id);}).catch(e=>{m.starting=false;_rerender();toast("Start failed: "+((e&&e.message)||e));});};
const _stopMission=stopMission;stopMission=function(m){if(!online)return _stopMission(m);m.stopping=true;_rerender();return B.StopMission(m.id).then(()=>{m.up=false;m.starting=false;m.stopping=false;_rerender();toast("Stopped "+m.id);}).catch(e=>{m.stopping=false;_rerender();toast("Stop failed: "+((e&&e.message)||e));});};
let statusRefreshBusy=false;async function refreshMissionStatuses(){if(!online||statusRefreshBusy)return;statusRefreshBusy=true;try{const states=await B.MissionStatuses();let changed=false;for(const m of MISSIONS){if(m.engine==="nix"||m.starting||m.stopping||states[m.id]==null)continue;const up=states[m.id]==="up";if(m.up!==up){m.up=up;changed=true;}}if(changed)_rerender();}catch(e){}finally{statusRefreshBusy=false;}}
setInterval(refreshMissionStatuses,4000);
/* Engine doctor: a modal (like `rfswift doctor` in the CLI) showing the state
   of every container engine, with Lima VM start/stop controls. Engines are
   only probed while the modal is open - no background polling. */
let ENGINES=[],NIXSTAT=null,AUDIOSTAT=null,engineBusy=false;
const engineModal=$("#engineModal");
async function loadEngineState(){try{ENGINES=await B.ContainerEngines()||[];}catch(e){ENGINES=[];}try{NIXSTAT=(typeof B.NixEngineStatus==="function")?await B.NixEngineStatus():null;}catch(e){NIXSTAT=null;}try{AUDIOSTAT=(HOST_OS!=="windows"&&typeof B.HostAudioStatus==="function")?await B.HostAudioStatus():null;}catch(e){AUDIOSTAT=null;}renderEngineRows();}
async function refreshEngines(){if(!online||engineBusy)return;if($("#engineRows .engpanel:not([hidden])"))return;/* don't wipe an open management panel mid-edit */await loadEngineState();}
function renderEngineRows(){const host=$("#engineRows");if(!host)return;
  /* The Nix engine needs no container daemon, so its store panel (and GC button)
     must render even when Docker/Podman/Lima are all absent. Show the container
     note only in place of the engine rows, then always append the Nix panel. */
  const engHTML=ENGINES.length?ENGINES.map(engineBlockHTML).join(""):"<p>No container engine detected. Install Docker, Podman or Lima.</p>";
  host.innerHTML=engHTML+hostAudioHTML()+nixMaintHTML();
  wireEngineDoctor();
}
function engineBlockHTML(e){const cls=e.state==="running"?"ok":e.state==="starting"?"med":"low";const label=(ENGNAME[e.name]||e.name)+(e.instance?" - "+e.instance:"");const running=e.state==="running"||e.state==="starting";let vmbtn="";if(e.vm&&e.available){vmbtn=running?`<button class="btn ghost sm" data-engstop="${esc(e.name)}" title="Stop the Lima VM and the containers inside it">Stop VM</button>`:`<button class="btn sm" data-engstart="${esc(e.name)}" title="Start the Lima VM (the first start creates it and can take several minutes)">Start VM</button>`;}
  const canManage=e.available&&running;
  let acts=`<button class="btn ghost sm" data-prunetoggle="${esc(e.name)}" ${canManage?"":"disabled"} title="Free disk space on this engine">Reclaim space...</button>`;
  if(e.vm)acts+=`<button class="btn ghost sm" data-limaset ${e.available?"":"disabled"}>VM settings...</button><button class="btn ghost sm engdanger" data-limareset ${e.available?"":"disabled"}>Reset VM...</button>`;
  const prune=`<div class="engpanel" data-prunepanel="${esc(e.name)}" hidden><div class="prunechecks"><label><input type="checkbox" data-pk="images" checked> Dangling images</label><label title="Removes every image no container uses - including tagged images left by deleted containers. They must be pulled again next time."><input type="checkbox" data-pk="unused"> Unused images (incl. tagged)</label><label><input type="checkbox" data-pk="cache" checked> Build cache</label><label><input type="checkbox" data-pk="volumes"> Unused volumes</label><label><input type="checkbox" data-pk="networks"> Unused networks</label></div><div class="prunefoot"><button class="btn sm" data-prunerun="${esc(e.name)}">Reclaim</button><span class="phint" data-prunestatus>"Unused images" reclaims tagged images from deleted containers (re-pulled later). Volumes/networks are removed only when unused.</span></div></div>`;
  let limaPanel="";if(e.vm)limaPanel=`<div class="engpanel" data-limapanel hidden><div class="limagrid"><label class="fld">CPUs<input type="number" min="1" data-lset="cpus"></label><label class="fld">Memory<input data-lset="memory" placeholder="8GiB"></label><label class="fld">Disk<input data-lset="disk" placeholder="100GiB"></label><label class="fld">VM type<select data-lset="vmtype"><option value="qemu">qemu (USB passthrough)</option><option value="vz">vz (Apple Virtualization)</option></select></label></div><div class="prunefoot"><button class="btn sm" data-limaapply>Apply</button><span class="phint">CPU/memory apply in place. Disk or VM-type changes recreate the VM (containers &amp; images inside are lost; host workspaces are kept).</span></div></div>`;
  return `<div class="engblock"><div class="engrow"><span class="chip ${cls}"><span class="d"></span>${esc(label)} - ${esc(e.state)}</span><span class="engsock" title="${esc(e.socket||"")}">${esc(e.socket||"")}</span>${vmbtn}</div><div class="engacts">${acts}</div>${prune}${limaPanel}</div>`;}
/* Host audio block: the PulseAudio/PipeWire TCP module containers play through
   (Linux/macOS; Windows containers use the WSLg socket, nothing to manage). */
function hostAudioHTML(){const s=AUDIOSTAT;if(!s||!s.supported)return "";const cls=s.enabled?"ok":s.running?"med":"low",state=s.enabled?"enabled":s.running?"not enabled":"no audio server";
  const btn=s.enabled?`<button class="btn ghost sm" data-audiodisable title="Unload ${esc(s.port?"the TCP module on port "+s.port:"the TCP module")} - running containers lose sound">Disable</button>`:`<button class="btn sm" data-audioenable ${s.running?"":"disabled"} title="Load module-native-protocol-tcp so containers reach the host audio server (same as rfswift host audio enable)">Enable</button>`;
  return `<div class="engblock"><div class="engrow"><span class="chip ${cls}"><span class="d"></span>Host audio - ${esc(s.system==="pipewire"?"PipeWire":s.system==="pulseaudio"?"PulseAudio":"none")} - ${esc(state)}</span><span class="engsock" style="direction:ltr" title="${esc(s.detail||"")}">${esc(s.server||"")}</span>${btn}</div><div class="engacts"><span class="phint">${esc(s.detail||"")}</span></div></div>`;}
/* Nix engine block: natively on Linux/macOS, inside a WSL 2 distribution on
   Windows (NixEngineStatus tells which, and whether that distribution has Nix
   and the Linux rfswift yet; NixWSLSetup provisions it, streaming its log). */
function nixMaintHTML(){if(!NIX_OK)return "";const s=NIXSTAT;
  let head=`<span class="chip low"><span class="d"></span>Nix - store</span><span class="engsock">reclaim unreferenced store paths</span>`,setup="",log="",gcDisabled="";
  if(s){const cls=s.ready?"ok":"med",label=s.host==="wsl"?("Nix - WSL 2"+(s.distro?" - "+s.distro:"")):"Nix - native";const detail=s.detail||(s.ready?"ready":"missing "+(s.missing||[]).join(", "));
    head=`<span class="chip ${cls}"><span class="d"></span>${esc(label)} - ${s.ready?"ready":"not ready"}</span><span class="engsock" style="direction:ltr" title="${esc(detail)}">${esc(detail)}</span>`;
    if(s.canSetup)setup=`<button class="btn sm" data-nixsetup title="Install Nix (flakes) and the Linux rfswift CLI in the WSL 2 distribution, as root - no password prompt. Needs a network connection.">Set up Nix in WSL 2</button>`;
    if(s.host==="wsl")log=`<div class="engpanel" data-nixsetuplog hidden><pre class="nixsetuplog" data-nixsetupout></pre></div>`;
    if(!s.ready)gcDisabled="disabled";}
  return `<div class="engblock"><div class="engrow">${head}${setup}</div><div class="engacts"><button class="btn ghost sm" data-nixgc ${gcDisabled} title="nix store gc - RF Swift environments are kept by their gcroots">Collect garbage</button>${s&&s.workspaceRoot?`<span class="phint" title="${esc(s.workspaceRoot)}">Workspaces: ${esc(s.workspaceRoot)}</span>`:""}</div>${log}</div>`;}
function wireEngineDoctor(){const host=$("#engineRows");
  $$("[data-engstart]",host).forEach(b=>b.onclick=async()=>{engineBusy=true;b.disabled=true;b.textContent="Starting...";toast("Starting "+(ENGNAME[b.dataset.engstart]||b.dataset.engstart)+" - the first start can take several minutes");try{await B.StartContainerEngine(b.dataset.engstart);toast("Engine is running");await hydrateMissions();}catch(e){toast("Engine start failed: "+((e&&e.message)||e));}finally{engineBusy=false;refreshEngines();}});
  $$("[data-engstop]",host).forEach(b=>b.onclick=async()=>{const name=b.dataset.engstop;if(!await dangerConfirm({title:"Stop Lima VM?",target:ENGNAME[name]||name,message:"Stopping the VM also stops every container running inside it.",action:"Stop VM"}))return;engineBusy=true;b.disabled=true;b.textContent="Stopping...";try{await B.StopContainerEngine(name);toast("VM stopped");await hydrateMissions();}catch(e){toast("Engine stop failed: "+((e&&e.message)||e));}finally{engineBusy=false;refreshEngines();}});
  $$("[data-prunetoggle]",host).forEach(b=>b.onclick=()=>{const p=host.querySelector(`[data-prunepanel="${b.dataset.prunetoggle}"]`);if(p)p.hidden=!p.hidden;});
  $$("[data-prunerun]",host).forEach(b=>b.onclick=async()=>{const name=b.dataset.prunerun,panel=b.closest(".engpanel"),status=$("[data-prunestatus]",panel);const g=k=>!!$(`[data-pk="${k}"]`,panel)?.checked;if(!(g("images")||g("unused")||g("cache")||g("volumes")||g("networks"))){toast("Select at least one target");return;}if(g("unused")&&!await dangerConfirm({title:"Remove unused images?",target:(ENGNAME[name]||name),message:"This removes every image not used by a running or stopped container, including tagged RF-Swift images left by deleted containers. They will be pulled again the next time you need them.",action:"Remove unused images"}))return;engineBusy=true;b.disabled=true;b.textContent="Reclaiming...";status.textContent="Reclaiming...";try{const r=await B.PruneEngine(name,g("images"),g("unused"),g("cache"),g("volumes"),g("networks"));status.textContent=r.detail||("reclaimed "+(r.reclaimedStr||"0 B"));toast("Reclaimed "+(r.reclaimedStr||"space")+" on "+(ENGNAME[name]||name));}catch(e){status.textContent="Failed: "+((e&&e.message)||e);}finally{engineBusy=false;b.disabled=false;b.textContent="Reclaim";}});
  $$("[data-limaset]",host).forEach(b=>b.onclick=async()=>{const panel=host.querySelector("[data-limapanel]");if(!panel)return;if(panel.hidden){try{const s=await B.GetLimaSpecs();$('[data-lset="cpus"]',panel).value=s.cpus||"";$('[data-lset="memory"]',panel).value=s.memory||"";$('[data-lset="disk"]',panel).value=s.disk||"";$('[data-lset="vmtype"]',panel).value=s.vmType||"qemu";}catch(e){toast("Could not read VM settings: "+((e&&e.message)||e));}}panel.hidden=!panel.hidden;});
  $$("[data-limaapply]",host).forEach(b=>b.onclick=async()=>{const panel=b.closest(".engpanel"),cpus=parseInt($('[data-lset="cpus"]',panel).value||"0",10)||0,memory=$('[data-lset="memory"]',panel).value.trim(),disk=$('[data-lset="disk"]',panel).value.trim(),vmtype=$('[data-lset="vmtype"]',panel).value;if(disk||vmtype){if(!await dangerConfirm({title:"Recreate the Lima VM?",target:"rfswift VM",message:"Changing disk size or VM type recreates the VM. Containers and images inside it are lost; bind-mounted host workspaces are preserved.",action:"Apply & recreate"}))return;}engineBusy=true;b.disabled=true;b.textContent="Applying...";toast("Applying VM settings - this can take a while");try{const msg=await B.SetLimaSpecs(cpus,memory,disk,vmtype,false);toast(msg||"Settings applied");await hydrateMissions();}catch(e){toast("Apply failed: "+((e&&e.message)||e));}finally{engineBusy=false;b.disabled=false;b.textContent="Apply";refreshEngines();}});
  $$("[data-limareset]",host).forEach(b=>b.onclick=async()=>{if(!await dangerConfirm({title:"Reset the Lima VM?",target:"rfswift VM",message:"This deletes the VM and recreates it clean from the template. All containers and images inside are lost; bind-mounted host workspaces are preserved.",action:"Delete & recreate"}))return;engineBusy=true;b.disabled=true;b.textContent="Resetting...";toast("Recreating the Lima VM - this can take several minutes");try{const msg=await B.LimaResetVM();toast(msg||"VM recreated");await hydrateMissions();}catch(e){toast("Reset failed: "+((e&&e.message)||e));}finally{engineBusy=false;b.disabled=false;b.textContent="Reset VM...";refreshEngines();}});
  $$("[data-audioenable],[data-audiodisable]",host).forEach(b=>b.onclick=async()=>{const enable=b.hasAttribute("data-audioenable");b.disabled=true;b.textContent=enable?"Enabling...":"Disabling...";try{const st=enable?await B.HostAudioEnable():await B.HostAudioDisable();toast((st&&st.detail)||(enable?"Host audio server enabled":"Host audio server disabled"));}catch(e){toast((enable?"Enable":"Disable")+" host audio failed: "+((e&&e.message)||e));}finally{await loadEngineState();}});
  const gc=$("[data-nixgc]",host);if(gc)gc.onclick=async()=>{gc.disabled=true;gc.textContent="Collecting...";toast("Running nix store gc...");try{const out=await B.NixGarbageCollect();toast("GC done - "+(String(out).split("\n").filter(Boolean).pop()||"complete"));}catch(e){toast("GC failed: "+((e&&e.message)||e));}finally{gc.disabled=false;gc.textContent="Collect garbage";}};
  const ns=$("[data-nixsetup]",host);if(ns)ns.onclick=async()=>{const panel=$("[data-nixsetuplog]",host),out=$("[data-nixsetupout]",host);if(panel)panel.hidden=false;if(out)out.textContent="Provisioning the WSL 2 distribution (systemd, Nix, rfswift)...\n";engineBusy=true;ns.disabled=true;ns.textContent="Setting up...";toast("Setting up Nix in WSL 2 - downloads Nix and rfswift, a few minutes");try{const st=await B.NixWSLSetup();toast(st&&st.ready?"Nix engine ready in WSL 2 ("+(st.distro||"")+")":"Setup finished - see the log");}catch(e){toast("Setup failed: "+((e&&e.message)||e));if(out)out.textContent+="\n"+((e&&e.message)||e)+"\n";}finally{engineBusy=false;await loadEngineState();await hydrateMissions();}};}
/* USB passthrough manager. macOS: hot-plug host devices into the Lima VM over
   QMP (`rfswift macusb attach/detach`). Windows: forward them into the WSL 2 VM
   that Docker Desktop and Podman run in, through usbipd-win (`rfswift usb
   attach/detach`); sharing a device the first time needs one administrator
   approval (a UAC prompt for usbipd.exe), attach/detach never do. The backend
   reports USBSupported()=false where neither applies. */
const usbModal=$("#usbModal");
let usbSupportedCache=null,usbBackendCache="",usbFromCreateForm=false;
async function usbIsSupported(){if(usbSupportedCache!==null)return usbSupportedCache;try{usbSupportedCache=await B.USBSupported();}catch(e){usbSupportedCache=false;}if(usbSupportedCache){try{usbBackendCache=await B.USBBackend();}catch(e){usbBackendCache="";}}return usbSupportedCache;}
function usbIsWin(){return usbBackendCache==="usbipd";}
/* On Windows every engine lives in the WSL 2 VM - Docker Desktop, Podman and
   the Nix engine's distribution share its kernel - so one usbipd attach serves
   containers and Nix environments alike. */
function usbEngineHasPassthrough(engine){return engine==="lima"||(HOST_OS==="windows"&&(engine==="docker"||engine==="podman"||engine==="nix"));}
function usbForNix(){return HOST_OS==="windows"&&((usbFromCreateForm&&$("#cm_engine")&&$("#cm_engine").value==="nix")||(!usbFromCreateForm&&contextMission&&contextMission.engine==="nix"));}
function usbModalCopy(){const win=usbIsWin(),nix=usbForNix();$("#usbTitle").textContent=win?(nix?"USB passthrough - Nix environment (WSL 2, usbipd)":"USB passthrough - WSL 2 (usbipd)"):"USB passthrough - Lima VM";
  $("#usbIntro").innerHTML=win?(nix?'Forward a host USB device (SDR, Proxmark, HackRF...) into the WSL 2 distribution that runs this Nix environment; the tools then see it under <span class="mono">/dev/bus/usb</span>. Tools run as your Linux user, so use <b>Install device rules</b> on the mission once (udev rules of the environment) for non-root access, and replug the device. The first time a device is shared, Windows asks for administrator approval (a UAC prompt for <span class="mono">usbipd.exe</span>); attaching and detaching never need it. GUI equivalent of <span class="mono">rfswift usb attach</span>.':'Forward a host USB device (SDR, Proxmark, HackRF...) into the WSL 2 VM that Docker Desktop, Podman and the Nix engine run in, so containers and Nix environments can use it under <span class="mono">/dev/bus/usb</span>. The first time a device is shared, Windows asks for administrator approval (a UAC prompt for <span class="mono">usbipd.exe</span>); attaching and detaching never need it. GUI equivalent of <span class="mono">rfswift usb attach</span>.'):'Forward a host USB device (SDR, Proxmark, HackRF...) into the Lima VM over QMP hot-plug, so containers running on the Lima engine can use it. The VM must be running. This is the GUI equivalent of <span class="mono">rfswift macusb attach</span>.';
  $("#usbVMTitle").textContent=win?"What WSL 2 currently sees":"What the VM currently sees";$("#usbApplyRow").style.display=(usbFromCreateForm&&!nix)?"flex":"none";}
async function openUSBModal(fromCreate=false){if(!online){toast("Backend not connected");return;}if(!await usbIsSupported()){toast(HOST_OS==="windows"?"USB passthrough needs usbipd-win: winget install usbipd":"USB passthrough is available on macOS (Lima) and Windows (usbipd)");return;}usbFromCreateForm=fromCreate===true;usbModalCopy();$("#usbRows").innerHTML="<p>Scanning USB devices...</p>";$("#usbVMInfo").textContent="-";$("#usbHostInfo").textContent="";usbModal.classList.add("open");refreshUSB();}
async function refreshUSB(){if(!online)return;const host=$("#usbRows");try{renderUSBRows(await B.ListHostUSB()||[]);}catch(e){host.innerHTML="<p>USB scan failed: "+esc((e&&e.message)||e)+"</p>";}
  try{const info=await B.USBHostInfo();$("#usbHostInfo").textContent=((info&&info.notes)||[]).join("\n");}catch(e){$("#usbHostInfo").textContent="";}
  try{$("#usbVMInfo").textContent=(await B.VMUSBInfo())||(usbIsWin()?"(no USB devices attached to WSL 2)":"(no USB devices attached to the VM)");}catch(e){$("#usbVMInfo").textContent=usbIsWin()?"WSL 2 did not answer: "+((e&&e.message)||e):"VM not running, or no USB bus yet.";}}
function usbRowHTML(d,i,win){const sn=d.serial&&d.serial!=="Not Provided"?" - "+esc(d.serial):"",desc=d.description?" - "+esc(d.description):"",bus=win&&d.busId?"  bus "+esc(d.busId):"";
  const label=win?(d.attached?"in WSL 2":d.state==="unplugged"?"unplugged":d.shared?"shared":"host"):(d.attached?"in VM":"host"),cls=d.attached?"ok":(win&&d.shared&&d.state!=="unplugged")?"med":"low";
  let btns="";
  if(!win)btns=`<button class="btn ${d.attached?"ghost ":""}sm" data-usbtoggle="${i}">${d.attached?"Detach":"Attach"}</button>`;
  else if(d.attached)btns=`<button class="btn ghost sm" data-usbtoggle="${i}" title="Give the device back to Windows (no administrator rights needed)">Detach</button>`;
  else if(d.state==="unplugged")btns=`<button class="btn ghost sm" data-usbunshare="${i}" title="Forget this device in usbipd (administrator approval)">Unshare</button>`;
  else{btns=`<button class="btn sm" data-usbtoggle="${i}" title="${d.shared?"Attach to WSL 2 (no administrator rights needed)":"Share once with administrator approval (UAC prompt for usbipd.exe), then attach to WSL 2"}">${d.shared?"Attach":"Share &amp; attach"}</button>`;if(d.shared)btns+=`<button class="btn ghost sm" data-usbunshare="${i}" title="Stop sharing (administrator approval)">Unshare</button>`;}
  const warn=d.warning?`<small class="usbwarn">${esc(d.warning)}</small>`:"";
  return `<div class="usbrow"><span class="chip ${cls}"><span class="d"></span>${label}</span><span class="usbname">${esc(d.name||"USB device")}<small>${esc(d.vendorId)}:${esc(d.productId)}${bus}${sn}${desc}</small>${warn}</span>${btns}</div>`;}
function renderUSBRows(devs){const host=$("#usbRows");if(!devs.length){host.innerHTML="<p>No forwardable USB devices found. Plug the device in and press Refresh.</p>";return;}
  const win=usbIsWin();host.innerHTML=devs.map((d,i)=>usbRowHTML(d,i,win)).join("");
  $$("#usbRows [data-usbtoggle]").forEach(b=>b.onclick=async()=>{const d=devs[+b.dataset.usbtoggle],was=!!d.attached,name=d.name||(win?d.busId:d.vendorId+":"+d.productId);
    if(!was&&d.warning&&!await dangerConfirm({title:"Forward this device?",target:name,message:d.warning,action:"Attach anyway"}))return;
    b.disabled=true;b.textContent=was?"Detaching...":"Attaching...";
    try{if(win){if(was){await B.DetachWinUSB(d.busId);toast("Detached "+name);}else{if(!d.shared)toast("Windows will ask for administrator approval to share "+name);const r=await B.AttachWinUSB(d.busId,true);toast((r&&r.already?"Already attached: ":r&&r.bound?"Shared and attached ":"Attached ")+name+" (WSL 2)");}}
      else{if(was)await B.DetachHostUSB(d.vendorId,d.productId);else await B.AttachHostUSB(d.vendorId,d.productId);toast((was?"Detached ":"Attached ")+name);}}
    catch(e){toast("USB "+(was?"detach":"attach")+" failed: "+((e&&e.message)||e));}finally{refreshUSB();}});
  $$("#usbRows [data-usbunshare]").forEach(b=>b.onclick=async()=>{const d=devs[+b.dataset.usbunshare],name=d.name||d.busId||d.guid;
    if(!await dangerConfirm({title:"Stop sharing this device?",target:name,message:"usbipd forgets the device and Windows asks for administrator approval. Attaching it again later needs another approval.",action:"Unshare"}))return;
    b.disabled=true;b.textContent="Unsharing...";try{await B.UnshareWinUSB(d.busId||d.guid);toast("Stopped sharing "+name);}catch(e){toast("Unshare failed: "+((e&&e.message)||e));}finally{refreshUSB();}});}
$("#usbClose").onclick=()=>usbModal.classList.remove("open");
$("#usbRefresh").onclick=()=>refreshUSB();
$("#usbApplyDefaults").onclick=()=>{$("#cm_usbotplug").click();};
usbModal.onclick=e=>{if(e.target===usbModal)usbModal.classList.remove("open");};
$("#cm_usb").onclick=()=>openUSBModal(true);
/* USB reachability of the container being created. Verified on Docker Desktop
   (WSL 2): /dev/bus/usb must be mapped AND major 189 allowed (c 189:* rwm);
   a bind mount alone lists the devices but open() fails, privileged mode is
   not required. Same check as the CLI (common.CheckUSBAccess). */
function usbAccessApplies(engine){return engine==="lima"||((HOST_OS==="windows"||HOST_OS==="linux")&&(engine==="docker"||engine==="podman"));}
function usbAccessForm(){const lines=id=>$(id).value.split("\n").map(x=>x.trim()).filter(Boolean);return [lines("#cm_devices"),lines("#cm_bindings"),$("#cm_cgroups").value.split(",").map(x=>x.trim()).filter(Boolean),$("#cm_priv").checked];}
let usbAccessTimer=null;
for(const id of ["#cm_devices","#cm_bindings","#cm_cgroups","#cm_priv"]){const el=$(id);if(el)el.addEventListener("input",scheduleUSBAccessHint);}
function scheduleUSBAccessHint(){clearTimeout(usbAccessTimer);usbAccessTimer=setTimeout(()=>{updateUSBAccessHint();updateDeviceCheckHint();},150);}
function deviceCheckForm(){const lines=id=>$(id).value.split("\n").map(x=>x.trim()).filter(Boolean);return [cmEngine.value,lines("#cm_devices"),lines("#cm_bindings")];}
function deviceIssuesText(check){return (check.issues||[]).map(i=>i.path+": "+i.reason).join("\n")+(check.advice?"\n\n"+check.advice:"");}
function removeDeviceIssues(issues){const specs=new Set((issues||[]).map(i=>i.spec));for(const id of ["#cm_devices","#cm_bindings"]){const el=$(id);el.value=el.value.split("\n").filter(l=>!specs.has(l.trim())).join("\n");}scheduleUSBAccessHint();toast((issues||[]).length+" unsupported device mapping(s) removed");}
async function updateDeviceCheckHint(){const box=$("#cm_devicecheck");if(!box)return;if(!online||cmEngine.value==="nix"){box.style.display="none";return;}
  try{const check=await B.DeviceMappingCheck(...deviceCheckForm());const issues=check.issues||[];if(!issues.length){box.style.display="none";return;}
    box.style.display="block";box.style.color="var(--med)";
    box.innerHTML="⚠ "+esc(check.engine||cmEngine.value)+" cannot map "+issues.length+" device mapping(s) on this host: "+issues.map(i=>"<span class=\"mono\">"+esc(i.path)+"</span> ("+esc(i.reason)+")").join(", ")+(check.advice?" "+esc(check.advice):"")+' <button class="btn ghost sm" id="cm_devicefix" type="button">Remove unsupported devices</button>';
    const fix=$("#cm_devicefix");if(fix)fix.onclick=()=>removeDeviceIssues(issues);}catch(e){box.style.display="none";}}
async function updateUSBAccessHint(){const box=$("#cm_usbaccess");if(!box)return;if(!online||!usbAccessApplies(cmEngine.value)){box.style.display="none";return;}
  try{const a=await B.USBAccessCheck(...usbAccessForm());box.style.display="block";box.style.color=a.level==="ok"?"var(--ink-2)":"var(--med)";
    box.innerHTML=(a.level==="ok"?"✓ USB access: ":"⚠ USB access: ")+esc(a.summary)+(a.advice?" "+esc(a.advice):"")+(a.level==="ok"?"":' <button class="btn ghost sm" id="cm_usbfix" type="button">Apply USB hotplug defaults</button>');
    const fix=$("#cm_usbfix");if(fix)fix.onclick=()=>$("#cm_usbotplug").click();}
  catch(e){box.style.display="none";}}
for(const id of ["#cm_devices","#cm_bindings","#cm_cgroups"]){const el=$(id);if(el)el.addEventListener("input",scheduleUSBAccessHint);}
$("#cm_priv").addEventListener("change",scheduleUSBAccessHint);
