const refreshTargets=$("#refreshTargets");if(refreshTargets)refreshTargets.onclick=()=>{if(!online){toast("Backend not connected");return;}toast("Refreshing targets ...");hydrateMissions().then(()=>toast("Targets refreshed"));};
let contextMission=null,pendingMissionCompanion=null;const missionContext=$("#missionContext"),configureModal=$("#configureModal");
function dangerConfirm({title,target,message,action}){return new Promise(resolve=>{const modal=$("#dangerModal"),done=value=>{modal.classList.remove("open");resolve(value);};$("#dangerTitle").textContent=title;$("#dangerTarget").textContent=target;$("#dangerMessage").textContent=message;$("#dangerConfirm").textContent=action;$("#dangerConfirm").onclick=()=>done(true);$("#dangerCancel").onclick=()=>done(false);$("#dangerClose").onclick=()=>done(false);modal.onclick=e=>{if(e.target===modal)done(false);};modal.classList.add("open");setTimeout(()=>$("#dangerCancel").focus(),0);});}
function workbenchDialog({title,target="",message="",action="Continue",inputLabel="",inputType="text",value=""}){return new Promise(resolve=>{const modal=$("#questionModal"),input=$("#questionInput"),wrap=$("#questionInputWrap"),hasInput=!!inputLabel,done=result=>{modal.classList.remove("open");resolve(result);};$("#questionTitle").textContent=title;$("#questionTarget").textContent=target;$("#questionTarget").style.display=target?"block":"none";$("#questionMessage").textContent=message;$("#questionMessage").style.display=message?"block":"none";$("#questionInputLabel").textContent=inputLabel;wrap.style.display=hasInput?"flex":"none";input.type=inputType;input.autocomplete=inputType==="password"?"new-password":"off";input.value=value;$("#questionConfirm").textContent=action;$("#questionCancel").textContent="Cancel";$("#questionConfirm").onclick=()=>done(hasInput?input.value:true);$("#questionCancel").onclick=()=>done(hasInput?null:false);$("#questionClose").onclick=()=>done(hasInput?null:false);modal.onclick=e=>{if(e.target===modal)done(hasInput?null:false);};input.onkeydown=e=>{if(e.key==="Enter"){e.preventDefault();$("#questionConfirm").click();}};modal.classList.add("open");setTimeout(()=>(hasInput?input:$("#questionCancel")).focus(),0);});}
function workbenchChoice({title,target="",message="",primary,secondary}){return new Promise(resolve=>{const modal=$("#questionModal"),done=value=>{modal.classList.remove("open");resolve(value);};$("#questionTitle").textContent=title;$("#questionTarget").textContent=target;$("#questionTarget").style.display=target?"block":"none";$("#questionMessage").textContent=message;$("#questionMessage").style.display=message?"block":"none";$("#questionInputWrap").style.display="none";$("#questionConfirm").textContent=primary;$("#questionCancel").textContent=secondary;$("#questionConfirm").onclick=()=>done(true);$("#questionCancel").onclick=()=>done(false);$("#questionClose").onclick=()=>done(null);modal.onclick=e=>{if(e.target===modal)done(null);};modal.classList.add("open");setTimeout(()=>$("#questionConfirm").focus(),0);});}
async function exportArchivePassword(target){const protect=await workbenchChoice({title:"Protect exported archive?",target,message:"Choose password protection to encrypt the archive and its notes. The password is never stored and cannot be recovered.",primary:"Use password",secondary:"No password"});if(protect===null)return null;if(!protect)return "";const password=await workbenchDialog({title:"Set archive password",target,message:"This password will be required to import or decrypt the archive.",inputLabel:"Archive password (required)",inputType:"password",action:"Set password"});if(password===null)return null;if(!password.trim()){toast("Enter a password to protect the archive");return null;}const confirm=await workbenchDialog({title:"Confirm archive password",target,message:"Re-enter the password. A lost password cannot be recovered.",inputLabel:"Confirm password (required)",inputType:"password",action:"Confirm and export"});if(confirm===null)return null;if(confirm!==password){toast("Archive passwords do not match");return null;}return password;}
function importArchivePassword(target){return workbenchDialog({title:"Archive password",target,message:"If the archive was password-protected during export, enter its password. Leave empty for an unencrypted archive.",inputLabel:"Archive password (optional)",inputType:"password",action:"Choose archive"});}
$("#importTarget").onclick=async()=>{if(!online){toast("Backend not connected");return;}if(targetScope==="nix"){const name=await workbenchDialog({title:"Import Nix environment",target:"Portable .rfenv archive",message:"Leave the name empty to use the name stored in the archive, or enter a new name to keep both copies.",inputLabel:"New environment name (optional)",action:"Continue"});if(name===null)return;const password=await importArchivePassword(name.trim()||"environment archive");if(password===null)return;openTransferProgress("import","nix",name.trim()||"environment archive");toast("Choose an RF Swift environment archive...");try{const result=await B.ImportNixEnvironment(name.trim(),password);if(result&&result.path){await hydrateMissions();toast("Nix environment imported from "+result.path);if(result.notesAvailable){const restore=await workbenchChoice({title:"Restore exported mission data?",target:result.target,message:"A mission companion was found next to this archive. Restoring it replaces portable Workbench data, including notes, captures, findings, reports, recordings, and audits.",primary:"Restore mission data",secondary:"Keep current data"});if(restore){await B.ImportTargetNotes(result.target,result.path,password);await hydrateMissions();toast("Exported mission data restored for "+result.target);}}}else $("#transferModal").classList.remove("open");}catch(e){failTransferProgress(e);toast("Environment import failed: "+((e&&e.message)||e));}return;}let engines;try{engines=(await B.ContainerEngines()||[]).filter(x=>x.available);}catch(e){toast("Engine discovery failed: "+((e&&e.message)||e));return;}if(!engines.length){toast("No Docker, Podman, or Lima engine is installed");return;}const preferred=engines.find(x=>x.name===engineFilter)||engines.find(x=>x.running)||engines.find(x=>x.active)||engines[0],engineName=await workbenchDialog({title:"Choose import engine",target:"Docker-compatible container archive",message:"Use docker, podman, or lima. Lima imports the image into Docker inside the RF Swift VM.",inputLabel:"Container engine",value:preferred.name,action:"Continue"});if(engineName===null)return;const selected=engines.find(x=>x.name===engineName.trim().toLowerCase());if(!selected){toast("Select an installed engine: "+engines.map(x=>x.name).join(", "));return;}if(!selected.running){const start=await workbenchDialog({title:(ENGNAME[selected.name]||selected.label)+" is stopped",target:"Container import needs a running engine",message:"Start it now? No archive will be imported unless you approve.",action:"Start engine"});if(!start)return;toast("Starting "+(ENGNAME[selected.name]||selected.name)+"...");try{await B.StartContainerEngine(selected.name);}catch(e){toast("Engine start failed: "+((e&&e.message)||e));return;}}const suggested=(selected.name==="podman"?"localhost/":"")+"rfswift-imported:"+new Date().toISOString().replace(/[-:TZ.]/g,"").slice(0,14),image=await workbenchDialog({title:"Import container archive",target:ENGNAME[selected.name]||selected.label,message:"Workbench first creates a verified local image from the archive, then automatically creates the mission container from it.",inputLabel:"Image name and tag",value:suggested,action:"Continue"});if(image===null)return;const password=await importArchivePassword(image.trim());if(password===null)return;openTransferProgress("import","container",image.trim());toast("Choose a container tar archive...");try{const imported=await B.ImportContainerArchive(selected.name,image.trim(),password),path=imported&&imported.path,importedImage=imported&&imported.image;if(path){const stamp=new Date().toISOString().replace(/[-:TZ.]/g,"").slice(0,14),missionName=await workbenchDialog({title:"Create imported container mission",target:ENGNAME[selected.name]||selected.label,message:"The archive filesystem is now available as an image. Enter a unique mission name; Workbench will create the container and restore its exported notes, captures, findings, reports, recordings, and audits.",inputLabel:"Mission name",value:"imported-"+stamp,action:"Create mission"});if(missionName===null){$("#transferModal").classList.remove("open");toast("Image imported; mission creation canceled");return;}const hasCompanion=await B.HasMissionCompanion(path);pendingMissionCompanion=hasCompanion?{path,password,auto:true}:null;$("#transferModal").classList.remove("open");cmOpen.click();cmEngine.value=selected.name;cmEngine.onchange();$("#cm_name").value=missionName.trim();$("#cm_title").value="Imported mission "+missionName.trim();$("#cm_image").value=importedImage;updateContainerImageHint();if(!hasCompanion)toast("Container archive has no mission companion; notes and captures cannot be restored");$("#cm_create").click();}else $("#transferModal").classList.remove("open");}catch(e){failTransferProgress(e);toast("Container import failed: "+((e&&e.message)||e));}};
function openMissionContext(x,y,m){contextMission=m;const nix=m.engine==="nix";$("#ctxLifecycle").style.display=nix?"none":"block";$("#ctxLifecycle").textContent=missionState(m)==="up"?"Stop container":"Start container";const audio=!nix&&HOST_OS!=="windows";$("#ctxAudio").style.display=audio?"block":"none";$("#ctxAudio").textContent=m.hostAudioOff?"Enable host audio server":"Disable host audio server";$("#ctxUSB").style.display=usbEngineHasPassthrough(m.engine)?"block":"none";$("#ctxUdev").style.display=nix?"block":"none";/* Update/check apply to every Nix env; rebuild/rollback need an eager profile, which lazy (on-demand) envs do not have. */$("#ctxCheckUpdate").style.display=nix?"block":"none";$("#ctxUpdate").style.display=nix?"block":"none";$("#ctxRebuild").style.display=nix&&!m.lazy?"block":"none";$("#ctxRollback").style.display=nix&&!m.lazy?"block":"none";$("#ctxDeleteClean").style.display=nix?"block":"none";$("#ctxDelete").textContent=nix?"Remove Nix environment...":"Delete container...";missionContext.style.left=Math.min(x,innerWidth-230)+"px";missionContext.style.top=Math.min(y,innerHeight-200)+"px";missionContext.classList.add("open");}
$("#ctxUSB").onclick=()=>{missionContext.classList.remove("open");openUSBModal();};$("#ctxUdev").onclick=async()=>{missionContext.classList.remove("open");const m=contextMission;if(!m)return;try{const rules=await B.NixUdevRules(m.id);const pending=(rules||[]).filter(r=>r.state!=="installed");if(!pending.length){toast("Device udev rules already installed");return;}toast("Installing "+pending.length+" device rule(s); you may be asked to authorise...");await B.InstallNixUdevRules(m.id);toast("Device rules installed - replug the device if it was connected");}catch(e){toast("Device rules: "+((e&&e.message)||e));}};
document.addEventListener("click",e=>{if(!missionContext.contains(e.target))missionContext.classList.remove("open");});
$("#ctxConfigure").onclick=()=>{missionContext.classList.remove("open");if(!contextMission)return;if(contextMission.engine==="nix"){const m=contextMission;cmEngine.value="nix";cmEngine.onchange();$("#cm_name").value=m.id;$("#cm_title").value=m.title||m.id;$("#cm_template").value=m.env;$("#cm_flaketype").value=m.flakeRef==="github:PentHertz/RF-Swift-nix"?"official":(m.flakeRef.startsWith("/")||m.flakeRef.startsWith("path:"))?"local":"custom";$("#cm_flaketype").onchange();$("#cm_flakeref").value=m.flakeRef;$("#cm_create").textContent="Update environment";cmModal.classList.add("open");return;}const rules=contextMission.cgroups||[];$("#cfgCurrent").textContent=rules.length?"Current device cgroup rules:\n"+rules.map(x=>"• "+x).join("\n"):"Current device cgroup rules: none";$("#cfgKind").value="cgroup";$("#cfgAction").value=rules.length?"remove":"add";$("#cfgValue").value=rules[0]||"";$("#cfgKind").onchange();$("#cfgTarget").textContent=contextMission.id+" - "+contextMission.engine;$("#cfgRisk").textContent=contextMission.engine==="docker"?"Docker rebinds the existing container in place, as RF-Swift does. It stops the container, edits Docker's persisted configuration, and restarts the Docker service; other running Docker containers may be interrupted.":"This engine applies runtime changes by stopping and recreating the container. Processes and non-persistent writable-layer changes may be interrupted; bind-mounted workspace data is preserved.";$("#cfgStatus").textContent="";configureModal.classList.add("open");};
const configureMissionHandler=$("#ctxConfigure").onclick;
$("#ctxConfigure").onclick=()=>{const selected=contextMission;configureMissionHandler();if(selected?.engine==="nix"){const ref=selected.flakeRef||"github:PentHertz/RF-Swift-nix";$("#cm_flaketype").value=ref.startsWith("github:PentHertz/RF-Swift-nix")?"official":(ref.startsWith("/")||ref.startsWith("path:"))?"local":"custom";$("#cm_flaketype").onchange();$("#cm_flakeref").value=ref;loadNixVersions(ref);}};
let installerMission=null,installerTools=[];function closeInstaller(){$("#installerModal").classList.remove("open");}
function installerStatus(message,state=""){const detail=$("#installerDetail");detail.textContent=message;detail.className="installerstatus"+(state?" "+state:"");}
$("#ctxInstall").onclick=()=>{missionContext.classList.remove("open");installerMission=contextMission;if(!installerMission)return;$("#installerTarget").textContent=installerMission.id+" - "+(installerMission.engine==="nix"?"persistent Nix profile":"container install scripts");$("#installerAllWrap").style.display=installerMission.engine==="nix"?"block":"none";$("#installerInstalledWrap").style.display=installerMission.engine==="nix"?"block":"none";$("#installerAll").checked=false;$("#installerQuery").value="";$("#installerResults").innerHTML="";$("#installerProgress").style.display="none";operationPercent={};installerStatus(installerMission.engine==="nix"?"Search RF Swift tools, or enable all nixpkgs for packages outside the catalog.":"Search installer functions discovered directly inside this container.");$("#installerInstall").disabled=true;$("#installerModal").classList.add("open");setTimeout(()=>$("#installerQuery").focus(),0);};
/* Nix environment maintenance: the GUI counterparts of `rfswift env update
   [--check] | rebuild | rollback`. Each is one backend call behind a confirm. */
async function runNixUpdate(m,confirm=true){const lazy=!!m.lazy;if(confirm){const go=await workbenchChoice({title:"Update Nix environment?",target:m.id,message:lazy?"On-demand environment: refreshes its flake so each tool builds the newer version on its next call, and upgrades the tools you installed into it now. Nothing is prebuilt.":"Refreshes the environment's flake lock (or picks up local flake changes) and rebuilds its profile. A failed build keeps the current generation untouched. This can take a while.",primary:lazy?"Update":"Update & rebuild",secondary:"Cancel"});if(!go)return;}toast("Updating "+m.id+(lazy?"...":" - this can take a while..."));try{await B.UpdateNixEnvironment(m.id);await hydrateMissions();toast("Environment "+m.id+" updated");}catch(e){toast("Update failed: "+((e&&e.message)||e));}}
$("#ctxUpdate").onclick=()=>{missionContext.classList.remove("open");const m=contextMission;if(m&&m.engine==="nix")runNixUpdate(m);};
$("#ctxCheckUpdate").onclick=async()=>{missionContext.classList.remove("open");const m=contextMission;if(!m||m.engine!=="nix")return;toast("Checking "+m.id+" for updates...");let report;try{report=String(await B.CheckNixEnvironmentUpdate(m.id)||"").trim();}catch(e){toast("Check failed: "+((e&&e.message)||e));return;}if(report.length>1800)report="..."+report.slice(-1800);const msg=$("#questionMessage");msg.style.whiteSpace="pre-wrap";msg.style.fontFamily="var(--mono,monospace)";msg.style.fontSize="12px";let go;try{go=await workbenchChoice({title:"Available updates",target:m.id,message:report||"No changes reported.",primary:"Update now",secondary:"Close"});}finally{msg.style.whiteSpace="";msg.style.fontFamily="";msg.style.fontSize="";}if(go)runNixUpdate(m,false);};
$("#ctxRebuild").onclick=async()=>{missionContext.classList.remove("open");const m=contextMission;if(!m||m.engine!=="nix"||m.lazy)return;const go=await workbenchChoice({title:"Rebuild Nix environment?",target:m.id,message:"Rebuilds the profile against its currently pinned flake lock without changing the lock - use it after editing a local flake's package definitions, or to re-realise the environment after a store garbage collection. The previous closure is kept as a generation.",primary:"Rebuild",secondary:"Cancel"});if(!go)return;toast("Rebuilding "+m.id+" - this can take a while...");try{await B.RebuildNixEnvironment(m.id);await hydrateMissions();toast("Environment "+m.id+" rebuilt");}catch(e){toast("Rebuild failed: "+((e&&e.message)||e));}};
$("#ctxRollback").onclick=async()=>{missionContext.classList.remove("open");const m=contextMission;if(!m||m.engine!=="nix"||m.lazy)return;let gens;try{gens=await B.ListNixGenerations(m.id)||[];}catch(e){toast("Could not list generations: "+((e&&e.message)||e));return;}if(!gens.length){toast(m.id+" has no previous generations to roll back to");return;}const fmt=g=>{const d=g.created?new Date(g.created):null;return g.name+(d&&!isNaN(d)?"  ("+d.toLocaleString()+")":"");};const listing=gens.slice(0,8).map(g=>"• "+fmt(g)).join("\n")+(gens.length>8?"\n• ... "+(gens.length-8)+" older":"");const msg=$("#questionMessage");msg.style.whiteSpace="pre-wrap";let pick;try{pick=await workbenchDialog({title:"Roll back Nix environment",target:m.id,message:"Saved generations, newest first. The generation displaced by the rollback is itself kept.\n"+listing,inputLabel:"Generation to restore",value:gens[0].name,action:"Roll back"});}finally{msg.style.whiteSpace="";}if(pick===null)return;const gen=pick.trim();if(gen&&!gens.some(g=>g.name===gen)){toast("Unknown generation "+gen);return;}toast("Rolling back "+m.id+"...");try{await B.RollbackNixEnvironment(m.id,gen);await hydrateMissions();toast("Environment "+m.id+" rolled back to "+(gen||gens[0].name));}catch(e){toast("Rollback failed: "+((e&&e.message)||e));}};
$("#ctxExport").onclick=async()=>{missionContext.classList.remove("open");const m=contextMission;if(!m)return;const password=await exportArchivePassword(m.id);if(password===null)return;openTransferProgress("export",m.engine==="nix"?"nix":"container",m.id);toast("Choose where to export "+m.id+"...");try{const path=await B.ExportTarget(m.id,m.engine,password);if(path)toast((m.engine==="nix"?"Environment":"Container")+" exported to "+path);else $("#transferModal").classList.remove("open");}catch(e){failTransferProgress(e);toast("Export failed: "+((e&&e.message)||e));}};
$("#installerSearch").onclick=async()=>{if(!installerMission)return;const btn=$("#installerSearch"),results=$("#installerResults");btn.disabled=true;btn.textContent="Searching...";results.innerHTML="";installerStatus("Discovering tools on "+installerMission.id+"...","working");try{installerTools=await B.SearchMissionTools(installerMission.id,$("#installerQuery").value.trim(),installerMission.engine==="nix"&&$("#installerAll").checked)||[];results.innerHTML=installerTools.map((x,i)=>`<option value="${i}">${esc(x.name)} - ${esc(x.source||"")}</option>`).join("");installerStatus(installerTools.length?installerTools.length+" tool(s) found. Select one to see details.":"No matching tool was found.",installerTools.length?"":"warning");}catch(e){installerStatus("Search failed: "+((e&&e.message)||e),"error");}finally{btn.disabled=false;btn.textContent="Search";}};
$("#installerResults").onchange=()=>{const x=installerTools[Number($("#installerResults").value)];$("#installerInstall").disabled=!x;$("#installerInstall").textContent=installerIsUpdate(x)?"Update selected tool":"Install selected tool";installerStatus(x?(x.name+" - "+(x.detail||x.source||"installable tool")):"Select a tool.");};
$("#installerInstalled").onclick=async()=>{if(!installerMission)return;const btn=$("#installerInstalled"),results=$("#installerResults");btn.disabled=true;results.innerHTML="";installerStatus("Listing the tools of "+installerMission.id+"...","working");try{installerTools=await B.ListMissionTools(installerMission.id)||[];results.innerHTML=installerTools.map((x,i)=>`<option value="${i}">${esc(x.name)} - ${esc(x.source||"")}</option>`).join("");$("#installerInstall").disabled=true;$("#installerInstall").textContent="Update selected tool";installerStatus(installerTools.length?installerTools.length+" tool(s). Select one and choose \"Update selected tool\": installed packages are upgraded in place, on-demand tools are rebuilt from the environment's flake so their next call runs the new version.":"This environment has no on-demand or installed tools to update.",installerTools.length?"":"warning");}catch(e){installerStatus("Listing failed: "+((e&&e.message)||e),"error");}finally{btn.disabled=false;}};
/* A candidate listed from the environment itself (source "installed" or
   "on-demand") is updated in place instead of installed: that is how a lazy
   environment refreshes tools one by one, having no whole profile to rebuild. */
function installerIsUpdate(x){return !!x&&(x.source==="installed"||x.source==="on-demand");}
$("#installerInstall").onclick=async()=>{const x=installerTools[Number($("#installerResults").value)];if(!x||!installerMission)return;const upd=installerIsUpdate(x),verb=upd?"Updat":"Install",done=upd?"updated":"installed";const btn=$("#installerInstall");btn.disabled=true;btn.textContent=verb+"ing...";operationPercent["package-install:"+installerMission.id]=0;renderOperationProgress("package-install",installerMission.id,2,"Starting "+verb.toLowerCase()+"ation");installerStatus(verb+"ing "+x.name+" in "+installerMission.id+". Build and download phases appear below.","working");try{if(upd)await B.UpdateMissionTool(installerMission.id,x.name);else await B.InstallMissionTool(installerMission.id,x.name);renderOperationProgress("package-install",installerMission.id,100,verb+"ation complete");installerStatus(x.name+" "+done+" successfully.","success");toast("✓ "+x.name+" "+done+" in "+installerMission.id,"success");}catch(e){$("#installerProgressFill").classList.remove("indeterminate");$("#installerProgressStage").textContent=verb+"ation failed";$("#installerProgressAmount").textContent="Failed";installerStatus(verb+"ation failed: "+((e&&e.message)||e),"error");toast("× "+verb+"ation of "+x.name+" failed","error");}finally{btn.disabled=false;btn.textContent=upd?"Update selected tool":"Install selected tool";}};
$("#installerClose").onclick=closeInstaller;$("#installerCancel").onclick=closeInstaller;$("#installerModal").onclick=e=>{if(e.target.id==="installerModal")closeInstaller();};$("#installerQuery").onkeydown=e=>{if(e.key==="Enter")$("#installerSearch").click();};
$("#ctxLifecycle").onclick=()=>{missionContext.classList.remove("open");const m=contextMission;if(!m)return;missionState(m)==="up"?stopMission(m):startMission(m);};
/* Host audio server (PulseAudio/PipeWire TCP module): host-wide, remembered per target for its next starts. */
$("#ctxAudio").onclick=async()=>{missionContext.classList.remove("open");const m=contextMission;if(!m||!online)return;const enable=!!m.hostAudioOff;try{const st=await B.SetMissionHostAudio(m.id,enable);m.hostAudioOff=!enable;toast((st&&st.detail)||(enable?"Host audio server enabled":"Host audio server disabled"));}catch(e){toast((enable?"Enable":"Disable")+" host audio failed: "+((e&&e.message)||e));}refreshEngines();};
$("#ctxDelete").onclick=async()=>{missionContext.classList.remove("open");const m=contextMission;if(!m)return;const nix=m.engine==="nix",message=nix?"This removes its manifest, lazy shims and GC root. Its workspace, findings and notes are preserved. Store paths are not reclaimed until garbage collection.":"This stops all processes and force-removes the writable container layer. Data stored only in that layer can be lost.\n\nPreserved: named volumes, bind-mounted workspace files, images, findings and notes.";if(!await dangerConfirm({title:nix?"Remove Nix environment?":"Delete container?",target:m.id,message,action:nix?"Remove environment":"Delete container"}))return;try{if(nix)await B.DeleteNixEnvironment(m.id,false);else await B.DeleteContainer(m.id);await hydrateMissions();toast((nix?"Removed environment ":"Deleted container ")+m.id+"; workspace data was preserved");}catch(e){toast("Delete failed: "+((e&&e.message)||e));}};
$("#ctxDeleteClean").onclick=async()=>{missionContext.classList.remove("open");const m=contextMission;if(!m||m.engine!=="nix")return;const warning="This deletes its GC root, then removes ALL unreferenced Nix store paths-not only this environment. Other unrooted builds and cached development outputs may need to be downloaded or compiled again.\n\nWorkspaces, findings and notes remain.";if(!await dangerConfirm({title:"Remove environment and clean Nix store?",target:m.id,message:warning,action:"Remove and clean"}))return;toast("Removing environment and cleaning Nix store...");try{await B.DeleteNixEnvironment(m.id,true);await hydrateMissions();toast("Environment removed and unreferenced store paths cleaned");}catch(e){toast("Nix cleanup failed: "+((e&&e.message)||e));}};
$("#ctxDeleteMission").onclick=async()=>{missionContext.classList.remove("open");const m=contextMission;if(!m)return;const warning="This permanently deletes the "+(m.engine==="nix"?"Nix environment":"container")+" and all Workbench-owned data for this mission:\n\n• notes and managed images\n• findings and secrets metadata\n• imported captures and reports\n• terminal recordings and mission settings\n\nExternal bind-mounted directories, named container volumes, and images are not deleted. This action cannot be undone.";if(!await dangerConfirm({title:"Delete mission completely?",target:m.id,message:warning,action:"Delete mission permanently"}))return;toast("Deleting mission "+m.id+"...");try{await B.DeleteMissionCompletely(m.id,m.engine);await hydrateMissions();toast("Mission "+m.id+" was permanently deleted");}catch(e){toast("Complete mission deletion failed: "+((e&&e.message)||e));}};
$("#configureClose").onclick=()=>configureModal.classList.remove("open");configureModal.onclick=e=>{if(e.target===configureModal)configureModal.classList.remove("open");};
const cfgHints={capability:"NET_ADMIN",cgroup:"c 189:* rwm",gpu:"all or 0,1","exposed-port":"8080/tcp","published-port":"127.0.0.1:8080:80/tcp"};
$("#cfgKind").onchange=()=>{const binding=["volume","device-bind","device"].includes($("#cfgKind").value);$("#cfgBinding").style.display=binding?"flex":"none";$("#cfgValueWrap").style.display=binding?"none":"flex";$("#cfgValue").placeholder=cfgHints[$("#cfgKind").value]||"";};
$("#cfgBrowse").onclick=()=>B.SelectHostPath($("#cfgKind").value==="volume").then(p=>{if(p){$("#cfgSource").value=p;if(!$("#cfgTargetPath").value)$("#cfgTargetPath").value=p;}});
$("#cfgApply").onclick=async()=>{if(!contextMission)return;const btn=$("#cfgApply"),status=$("#cfgStatus");btn.disabled=true;status.textContent=contextMission.engine==="docker"?"Rebinding existing Docker container...":"Applying; the container may be recreated...";try{await B.ConfigureContainer(contextMission.id,{kind:$("#cfgKind").value,value:$("#cfgValue").value.trim(),source:$("#cfgSource").value.trim(),target:$("#cfgTargetPath").value.trim(),add:$("#cfgAction").value==="add"});await hydrateMissions();configureModal.classList.remove("open");toast(contextMission.engine==="docker"?"Docker container rebound in place":"Container configuration updated");}catch(e){status.textContent="Error: "+((e&&e.message)||e);}finally{btn.disabled=false;}};
function renderMissionTemplates(){const s=$("#cm_template"),list=$("#cm_templates");if(!s||!list)return;list.innerHTML=MISSION_TEMPLATES.map(t=>`<option value="${esc(t.name)}">${esc(t.category||"tools")} - ${esc(t.description||"")}</option>`).join("");if(!s.value&&MISSION_TEMPLATES[0])s.value=MISSION_TEMPLATES[0].name;const t=MISSION_TEMPLATES.find(x=>x.name===s.value)||MISSION_TEMPLATES[0];$("#cm_hint").textContent=t?t.description:"No Nix catalog environments found";}
function renderContainerProfiles(){const s=$("#cm_profile");if(!s)return;s.innerHTML='<option value="">Custom</option>'+CONTAINER_PROFILES.map(p=>`<option value="${esc(p.name)}">${esc(p.name)}</option>`).join("");}
const cmOpen=$("#createMission"),cmModal=$("#missionModal"),cmEngine=$("#cm_engine");
function simpleImageName(value){const image=String(value||"").trim(),clean=image.replace(/^docker\.io\//,"");return /^penthertz\/rfswift_[^:]+:[^:]+$/i.test(clean)?clean.slice(clean.lastIndexOf(":")+1):image;}
function updateContainerImageHint(){const image=$("#cm_image").value.trim(),imported=/^(localhost\/)?rfswift-imported:/i.test(image);$("#cm_hint").textContent=image?(imported?`Image: ${image} - verified local imported image; no registry download is used.`:`Image: ${simpleImageName(image)} - RF-Swift resolves official short names automatically for ${cmEngine.options[cmEngine.selectedIndex].text}.`):"Enter an image name such as rfid or sdr_light.";}
function applyContainerDefaults(){const d=CONTAINER_DEFAULTS||{};$("#cm_bindings").value=(d.bindings||[]).join("\n");$("#cm_devices").value=(d.devices||[]).join("\n");$("#cm_cgroups").value=(d.cgroupRules||[]).join(", ");$("#cm_exposed").value=d.exposedPorts||"";$("#cm_ports").value=d.portBindings||"";$("#cm_seccomp").value=d.seccomp||"";$("#cm_network").value=d.network||"host";const known=new Set($$('[data-cmcap]').map(x=>x.dataset.cmcap)),caps=d.caps||[];$("#cm_caps").value=caps.filter(x=>!known.has(x)).join(",");$$('[data-cmcap]').forEach(x=>x.checked=caps.includes(x.dataset.cmcap));$("#cm_priv").checked=!!d.privileged;$("#cm_desktop").checked=!!d.desktopProto;$("#cm_desktopproto").value=d.desktopProto||"http";$("#cm_desktophost").value=d.desktopHost||"127.0.0.1";$("#cm_desktopport").value=d.desktopPort||"6080";$("#cm_desktoppass").value=d.desktopPassword||"";$("#cm_desktopssl").checked=!!d.desktopSSL;$("#cm_network").onchange();$("#cm_desktop").onchange();updateContainerImageHint();scheduleUSBAccessHint();}
function resetContainerCreateForm(){$("#cm_profile").value="";for(const id of ["#cm_workspace","#cm_gpucustom","#cm_image"]){const el=$(id);if(el)el.value="";}$("#cm_gpus").value="";$("#cm_realtime").checked=false;$("#cm_x11").checked=true;$("#cm_audio").checked=true;applyContainerDefaults();$("#cm_profilehint").textContent=CONTAINER_DEFAULTS?.path?"Base defaults: "+CONTAINER_DEFAULTS.path:"RF-Swift platform defaults";$("#cm_gpus").onchange();}
let nixVersionsLoading=false;
function shortCommit(value){return (value||"").slice(0,12);}
async function loadNixVersions(selectedRef=""){
 const select=$("#cm_nixversion"),hint=$("#cm_nixversion_hint"),refresh=$("#cm_nixversions_refresh");if(nixVersionsLoading)return;nixVersionsLoading=true;select.disabled=true;refresh.disabled=true;hint.style.color="var(--ink-3)";hint.textContent="Loading the latest commit and published release tags...";
 try{const versions=await B.NixRepositoryVersions("github:PentHertz/RF-Swift-nix"),items=[...(versions.latest?[versions.latest]:[]),versions.nightly,...(versions.releases||[])];select.innerHTML="";for(const item of items){const option=document.createElement("option");option.value=item.ref;option.textContent=item.kind==="latest"?`Latest · ${item.name} · ${shortCommit(item.commit)}`:item.kind==="nightly"?`Nightly · ${versions.defaultBranch} · ${shortCommit(item.commit)}`:`${item.name} · ${shortCommit(item.commit)}`;select.appendChild(option);}if(selectedRef&&!items.some(x=>x.ref===selectedRef)){const option=document.createElement("option");option.value=selectedRef;option.textContent=`Current mission · ${selectedRef}`;select.appendChild(option);}select.value=selectedRef||(versions.latest?.ref||versions.nightly.ref);$("#cm_flakeref").value=select.value;hint.textContent=versions.latest?"Latest uses the newest published tag; Nightly pins the newest GitHub commit.":"No release tag exists yet; Nightly pins the newest GitHub commit.";
 }catch(e){select.innerHTML='<option value="">Versions unavailable — use the reference below</option>';hint.style.color="var(--warn)";hint.textContent="Could not load GitHub versions: "+((e&&e.message)||e)+". You can still use a custom reference.";}finally{select.disabled=false;refresh.disabled=false;nixVersionsLoading=false;}
}
$("#cm_nixversion").onchange=()=>{if($("#cm_nixversion").value)$("#cm_flakeref").value=$("#cm_nixversion").value;};
$("#cm_nixversions_refresh").onclick=()=>loadNixVersions($("#cm_flakeref").value);
if(cmOpen)cmOpen.onclick=()=>{if(!online){toast("Backend not connected");return;}renderMissionTemplates();renderContainerProfiles();resetContainerCreateForm();$("#cm_progress").style.display="none";operationPercent={};$("#cm_create").textContent=targetScope==="nix"?"Create environment":"Create container";$("#cm_name").value="";$("#cm_title").value="";cmEngine.value=targetScope==="nix"?"nix":"docker";cmEngine.onchange();if(cmEngine.value==="nix")loadNixVersions();cmModal.classList.add("open");};
$("#missionClose").onclick=()=>cmModal.classList.remove("open");
cmEngine.onchange=()=>{const nix=cmEngine.value==="nix";$("#cm_template").style.display=nix?"block":"none";$("#cm_image").style.display=nix?"none":"block";$("#cm_nix").style.display=nix?"flex":"none";$("#cm_container").style.display=nix?"none":"block";$("#cm_usbrow").style.display=usbEngineHasPassthrough(cmEngine.value)?"flex":"none";if(nix)$("#cm_hint").textContent=(MISSION_TEMPLATES.find(x=>x.name===$("#cm_template").value)||{}).description||"";else updateContainerImageHint();scheduleUSBAccessHint();};
$("#cm_template").oninput=()=>{const t=MISSION_TEMPLATES.find(x=>x.name===$("#cm_template").value);$("#cm_hint").textContent=t?t.description:"Unknown Nix environment name";};
$("#cm_network").onchange=()=>$$('.cm_nat').forEach(x=>x.style.display=$("#cm_network").value==="nat"?"flex":"none");
$("#cm_gpus").onchange=()=>$("#cm_gpucustom").style.display=$("#cm_gpus").value==="custom"?"block":"none";
$("#cm_desktop").onchange=()=>$("#cm_desktopopts").style.display=$("#cm_desktop").checked?"block":"none";
$("#cm_desktopproto").onchange=()=>$("#cm_desktopport").value=$("#cm_desktopproto").value==="vnc"?"5900":"6080";
$("#cm_desktophost").onchange=()=>{const pub=$("#cm_desktophost").value==="0.0.0.0";$("#cm_desktopwarn").style.color=pub?"var(--crit)":"var(--ink-3)";$("#cm_desktopwarn").textContent=pub?"Warning: reachable from the network. Set a strong password and consider SSL/TLS.":"The selected RF-Swift image must include its desktop scripts. Local-only binding is recommended.";};
$("#cm_flaketype").onchange=()=>{const t=$("#cm_flaketype").value,ref=$("#cm_flakeref");ref.readOnly=t!=="custom";$("#cm_flakepick").style.display=t==="local"?"inline-block":"none";$("#cm_versionrow").style.display=t==="official"?"flex":"none";$("#cm_nixversion_hint").style.display=t==="official"?"block":"none";if(t==="official"&&!ref.value.startsWith("github:PentHertz/RF-Swift-nix")){ref.value="github:PentHertz/RF-Swift-nix";loadNixVersions();}if(t==="local")ref.value="";if(t==="custom")ref.readOnly=false;$("#cm_flakehint").textContent=t==="official"?"Choose Latest or a published release above.":t==="local"?"Select a local RF-Swift-nix checkout containing flake.nix.":"Enter a Nix flake reference such as github:owner/repo, path:/dir, or /dir.";};
$("#cm_flakepick").onclick=()=>B.SelectWorkspaceDirectory().then(p=>{if(p)$("#cm_flakeref").value=p;});
$("#cm_profile").onchange=()=>{const p=CONTAINER_PROFILES.find(x=>x.name===$("#cm_profile").value);applyContainerDefaults();if(!p){$("#cm_profilehint").textContent=CONTAINER_DEFAULTS?.path?"Base defaults: "+CONTAINER_DEFAULTS.path:"RF-Swift platform defaults";return;}$("#cm_profilehint").textContent=(p.description||"")+" - merged with "+(CONTAINER_DEFAULTS?.path||"platform config.ini");$("#cm_image").value=simpleImageName(p.image||p.name);updateContainerImageHint();if(p.network){$("#cm_network").value=p.network.startsWith("nat")?"nat":p.network;$("#cm_network").onchange();}for(const item of (p.bindings||"").split(",").filter(Boolean))addUniqueLine("#cm_bindings",item);for(const item of (p.devices||"").split(",").filter(Boolean))addUniqueLine("#cm_devices",item);const profileCaps=(p.caps||"").split(",").map(x=>x.trim()).filter(Boolean),allCaps=[...(CONTAINER_DEFAULTS?.caps||[]),...profileCaps],known=new Set($$('[data-cmcap]').map(x=>x.dataset.cmcap));$("#cm_caps").value=[...new Set(allCaps.filter(x=>!known.has(x)))].join(",");$$('[data-cmcap]').forEach(x=>x.checked=allCaps.includes(x.dataset.cmcap));const rules=[...(CONTAINER_DEFAULTS?.cgroupRules||[]),...(p.cgroups||"").split(",")].map(x=>x.trim()).filter(Boolean);$("#cm_cgroups").value=[...new Set(rules)].join(", ");if(p.exposedPorts)$("#cm_exposed").value=p.exposedPorts;if(p.portBindings)$("#cm_ports").value=p.portBindings;$("#cm_gpus").value=p.gpus||"";$("#cm_gpus").onchange();$("#cm_realtime").checked=!!p.realtime;$("#cm_priv").checked=!!p.privileged;$("#cm_x11").checked=!p.noX11;$("#cm_desktop").checked=!!p.desktop;$("#cm_desktopssl").checked=!!p.desktopSSL;$("#cm_desktop").onchange();scheduleUSBAccessHint();};
function profileKey(value){const raw=(value||"").trim().toLowerCase(),tag=raw.includes(":")?raw.slice(raw.lastIndexOf(":")+1):raw.includes("/")?raw.slice(raw.lastIndexOf("/")+1):raw;return tag.replace(/^rfswift[-_]?/,"").replace(/_/g,"-");}
$("#cm_image").oninput=()=>{updateContainerImageHint();const key=profileKey($("#cm_image").value),p=CONTAINER_PROFILES.find(x=>profileKey(x.name)===key||profileKey(x.image)===key);if(!p)return;$("#cm_profile").value=p.name;$("#cm_profile").onchange();toast("Applied RF-Swift profile: "+p.name);};
$("#cm_workspacepick").onclick=()=>B.SelectWorkspaceDirectory().then(p=>{if(p)$("#cm_workspace").value=p;});
function addUniqueLine(field,line){const ta=$(field);if(!ta||!line)return;const norm=x=>x.trim().replace(/:(?:ro|rw)$/i,""),wanted=norm(line);if(!ta.value.split("\n").some(x=>norm(x)===wanted))ta.value+=(ta.value.trim()?"\n":"")+line;}
function addPathLine(field,path,dest){if(!path)return;addUniqueLine(field,path+":"+(dest||path));}
$("#cm_binddir").onclick=async()=>{const p=await B.SelectHostPath(true);if(!p)return;const d=await workbenchDialog({title:"Add directory mount",target:p,inputLabel:"Path inside container",value:p,action:"Add mount"});if(d)addPathLine("#cm_bindings",p,d+":rw");};
$("#cm_bindfile").onclick=async()=>{const p=await B.SelectHostPath(false);if(!p)return;const d=await workbenchDialog({title:"Add file mount",target:p,inputLabel:"Path inside container",value:p,action:"Add mount"});if(d)addPathLine("#cm_bindings",p,d+":rw");};
$("#cm_devicebind").onclick=async()=>{const p=await B.SelectHostPath(false);if(!p)return;const d=await workbenchDialog({title:"Bind device path",target:p,inputLabel:"Device path inside container",value:p,action:"Add binding"});if(d)addPathLine("#cm_bindings",p,d+":rw");};
$("#cm_usbotplug").onclick=()=>{addUniqueLine("#cm_bindings","/dev/bus/usb:/dev/bus/usb:rw");const rules=$("#cm_cgroups").value.split(",").map(x=>x.trim()).filter(Boolean);if(!rules.includes("c 189:* rwm"))rules.push("c 189:* rwm");$("#cm_cgroups").value=rules.join(", ");toast("USB hotplug mount and cgroup rule applied");scheduleUSBAccessHint();};
$("#cm_devicepick").onclick=async()=>{const p=await B.SelectHostPath(false);if(!p)return;const d=await workbenchDialog({title:"Map device",target:p,inputLabel:"Device path inside container",value:p,action:"Add device"});if(d)addPathLine("#cm_devices",p,d);};
$("#cm_proxmark").onclick=()=>{addUniqueLine("#cm_devices","/dev/ttyACM0:/dev/ttyACM0");addUniqueLine("#cm_bindings","/dev/bus/usb:/dev/bus/usb:rw");const rules=$("#cm_cgroups").value.split(",").map(x=>x.trim()).filter(Boolean);if(!rules.includes("c 189:* rwm"))rules.push("c 189:* rwm");$("#cm_cgroups").value=rules.join(", ");scheduleUSBAccessHint();};
